//! Human readable byte size parsing and formatting.

fn unit_multiplier(unit: &str) -> Result<f64, String> {
    let v = match unit.to_lowercase().as_str() {
        "b" => 1.0,
        "k" | "kb" => 1_000.0,
        "ki" | "kib" => 1_024.0,
        "m" | "mb" => 1_000_000.0,
        "mi" | "mib" => 1_048_576.0,
        "g" | "gb" => 1_000_000_000.0,
        "gi" | "gib" => 1_073_741_824.0,
        "t" | "tb" => 1_000_000_000_000.0,
        "ti" | "tib" => 1_099_511_627_776.0,
        "p" | "pb" => 1_000_000_000_000_000.0,
        "pi" | "pib" => 1_125_899_906_842_624.0,
        "e" | "eb" => 1_000_000_000_000_000_000.0,
        "ei" | "eib" => 1_152_921_504_606_846_976.0,
        _ => return Err(format!("Failed to parse unit {:?}", unit)),
    };
    Ok(v)
}

/// Parses strings such as `100`, `100KB`, `0.5 MiB` into a number of bytes.
pub fn parse_bytesize(value: &str) -> Result<u64, String> {
    if let Ok(v) = value.parse::<u64>() {
        return Ok(v);
    }
    let number: String = value
        .chars()
        .take_while(|c| c.is_ascii_digit() || *c == '.')
        .collect();
    match number.parse::<f64>() {
        Ok(v) => {
            let suffix: String = value
                .chars()
                .skip_while(|c| c.is_whitespace() || c.is_ascii_digit() || *c == '.')
                .collect();
            match unit_multiplier(&suffix) {
                Ok(mul) => Ok((v * mul) as u64),
                Err(error) => Err(format!(
                    "couldn't parse {:?} into a known SI unit, {}",
                    suffix, error
                )),
            }
        }
        Err(error) => Err(format!(
            "couldn't parse {:?} into a ByteSize, {}",
            value, error
        )),
    }
}

/// Formats a size using binary units with one decimal (e.g. `58.9 KiB`).
pub fn format_size(bytes: u64) -> String {
    const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    if bytes < 1024 {
        return format!("{} B", bytes);
    }
    let mut value = bytes as f64;
    let mut idx = 0;
    while value >= 1024.0 && idx < UNITS.len() - 1 {
        value /= 1024.0;
        idx += 1;
    }
    format!("{:.1} {}", value, UNITS[idx])
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse() {
        assert_eq!(parse_bytesize("100"), Ok(100));
        assert_eq!(parse_bytesize("100KB"), Ok(100_000));
        assert_eq!(parse_bytesize("0.5MB"), Ok(500_000));
        assert_eq!(parse_bytesize("1 KB"), Ok(1000));
        assert!(parse_bytesize("abc").is_err());
    }

    #[test]
    fn format() {
        assert_eq!(format_size(0), "0 B");
        assert_eq!(format_size(60293), "58.9 KiB");
        assert_eq!(format_size(1048575), "1024.0 KiB");
        assert_eq!(format_size(1048576), "1.0 MiB");
    }
}
