use std::fs::File;
use std::io::Read;
use std::path::{Component, Path, PathBuf};

use walkdir::WalkDir;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ImageKind {
    Jpeg,
    Png,
    Gif,
    WebP,
}

/// Detects the image kind by looking at the first bytes of the buffer.
pub fn detect_kind(head: &[u8]) -> Option<ImageKind> {
    if head.len() >= 3 && head[0] == 0xFF && head[1] == 0xD8 && head[2] == 0xFF {
        return Some(ImageKind::Jpeg);
    }
    if head.len() >= 4 && head[0] == 0x89 && &head[1..4] == b"PNG" {
        return Some(ImageKind::Png);
    }
    if head.len() >= 3 && &head[0..3] == b"GIF" {
        return Some(ImageKind::Gif);
    }
    if head.len() >= 12 && &head[8..12] == b"WEBP" {
        return Some(ImageKind::WebP);
    }
    None
}

fn is_supported_image(path: &Path) -> bool {
    let mut file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return false,
    };
    let mut head = [0u8; 16];
    if file.read_exact(&mut head).is_err() {
        return false;
    }
    detect_kind(&head).is_some()
}

/// Expands the list of user supplied paths into the list of image files.
pub fn collect_files(inputs: &[PathBuf], recursive: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for input in inputs {
        if input.is_dir() {
            if recursive {
                for entry in WalkDir::new(input).follow_links(false).into_iter().flatten() {
                    if entry.file_type().is_dir() {
                        continue;
                    }
                    let path = entry.into_path();
                    if is_supported_image(&path) {
                        files.push(path);
                    }
                }
            } else if let Ok(rd) = std::fs::read_dir(input) {
                for entry in rd.flatten() {
                    let path = entry.path();
                    if path.is_dir() {
                        continue;
                    }
                    if is_supported_image(&path) {
                        files.push(path);
                    }
                }
            }
        } else if is_supported_image(input) {
            files.push(input.clone());
        }
    }
    files
}

/// Computes the directory shared by all the given files (using absolute,
/// non canonicalized paths).
pub fn compute_base_path(files: &[PathBuf]) -> Option<PathBuf> {
    let mut common: Option<Vec<Component>> = None;
    let mut owned: Vec<PathBuf> = Vec::new();
    for file in files {
        let abs = match std::path::absolute(file) {
            Ok(p) => p,
            Err(_) => continue,
        };
        let parent = abs.parent().map(|p| p.to_path_buf()).unwrap_or_default();
        owned.push(parent);
    }
    for parent in &owned {
        let comps: Vec<Component> = parent.components().collect();
        common = Some(match common {
            None => comps,
            Some(prev) => prev
                .iter()
                .zip(comps.iter())
                .take_while(|(a, b)| a == b)
                .map(|(a, _)| *a)
                .collect(),
        });
    }
    common.map(|comps| {
        let mut p = PathBuf::new();
        for c in comps {
            p.push(c.as_os_str());
        }
        p
    })
}
