//! Minimal terminal progress indicators (spinner and progress bar).

use std::io::{IsTerminal, Write};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;
use std::time::{Duration, Instant};

fn terminal_width(fd: i32) -> usize {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
            return ws.ws_col as usize;
        }
    }
    80
}

/// Spinner drawn on stderr while files are being collected.
pub struct Spinner {
    active: bool,
}

impl Spinner {
    pub fn start(enabled: bool, message: &str) -> Spinner {
        let active = enabled && std::io::stderr().is_terminal();
        if active {
            let width = terminal_width(libc::STDERR_FILENO);
            let line = format!("⠁ {}", message);
            let visible = line.chars().count();
            let pad = width.saturating_sub(visible);
            let mut err = std::io::stderr().lock();
            let _ = write!(err, "{}{}", line, " ".repeat(pad));
            let _ = err.flush();
        }
        Spinner { active }
    }

    pub fn finish(self) {
        if self.active {
            let mut err = std::io::stderr().lock();
            let _ = write!(err, "\r\x1b[2K");
            let _ = err.flush();
        }
    }
}

/// Progress bar drawn on stdout while files are being compressed.
pub struct ProgressBar {
    active: bool,
    total: u64,
    pos: AtomicU64,
    start: Instant,
    state: Mutex<DrawState>,
}

struct DrawState {
    drawn: bool,
    last_draw: Option<Instant>,
}

impl ProgressBar {
    pub fn new(enabled: bool, total: u64) -> ProgressBar {
        let active = enabled && std::io::stdout().is_terminal();
        let bar = ProgressBar {
            active,
            total,
            pos: AtomicU64::new(0),
            start: Instant::now(),
            state: Mutex::new(DrawState {
                drawn: false,
                last_draw: None,
            }),
        };
        if active {
            bar.draw(true);
        }
        bar
    }

    fn render(&self, pos: u64) -> String {
        let elapsed = self.start.elapsed().as_secs();
        let prefix = format!(
            "[{:02}:{:02}:{:02}] [",
            elapsed / 3600,
            (elapsed / 60) % 60,
            elapsed % 60
        );
        let suffix = format!("] {}/{}", pos, self.total);
        let width = terminal_width(libc::STDOUT_FILENO);
        let bar_width = width.saturating_sub(prefix.len() + suffix.len()).max(1);
        let mut bar = String::with_capacity(bar_width);
        if self.total == 0 || pos >= self.total {
            bar.extend(std::iter::repeat('#').take(bar_width));
        } else {
            let filled = (bar_width as u64 * pos / self.total) as usize;
            bar.extend(std::iter::repeat('#').take(filled));
            if filled < bar_width {
                bar.push('>');
                bar.extend(std::iter::repeat('-').take(bar_width - filled - 1));
            }
        }
        format!("{}{}{}", prefix, bar, suffix)
    }

    fn draw(&self, force: bool) {
        if !self.active {
            return;
        }
        let mut st = self.state.lock().unwrap();
        if !force {
            if let Some(last) = st.last_draw {
                if last.elapsed() < Duration::from_millis(50) {
                    return;
                }
            }
        }
        let pos = self.pos.load(Ordering::SeqCst);
        let line = self.render(pos);
        let mut out = std::io::stdout().lock();
        if st.drawn {
            let _ = write!(out, "\r\x1b[2K{}", line);
        } else {
            let _ = write!(out, "{}", line);
        }
        let _ = out.flush();
        st.drawn = true;
        st.last_draw = Some(Instant::now());
    }

    pub fn inc(&self) {
        self.pos.fetch_add(1, Ordering::SeqCst);
        self.draw(false);
    }

    pub fn finish(&self) {
        if !self.active {
            return;
        }
        self.pos.store(self.total, Ordering::SeqCst);
        self.draw(true);
    }
}
