//! Formatting of per-file results and of the final summary.

use colored::Colorize;
use std::path::PathBuf;

use crate::bytesize::format_size;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Status {
    Success,
    Skipped(String),
    Error(String),
}

#[derive(Debug, Clone)]
pub struct FileResult {
    pub input: PathBuf,
    pub output: PathBuf,
    pub original_size: u64,
    pub compressed_size: u64,
    pub status: Status,
}

/// Builds the `[-44.2 KiB | -75.13%]` part shared by file and summary lines.
pub fn format_diff(original: u64, compressed: u64) -> String {
    let (sign, diff) = if compressed > original {
        ("+", compressed - original)
    } else {
        ("-", original - compressed)
    };
    let pct = if original == 0 {
        0.0
    } else {
        (compressed as f64 - original as f64) / original as f64 * 100.0
    };
    let pct_abs = pct.abs();
    let size_str = format!("{}{}", sign, format_size(diff));
    let pct_str = format!("{}{:.2}%", sign, pct_abs);
    if compressed > original {
        format!("[{} | {}]", size_str.red(), pct_str.red())
    } else {
        format!("[{} | {}]", size_str.green(), pct_str.green())
    }
}

pub fn format_result(result: &FileResult) -> String {
    let label = match &result.status {
        Status::Success => "Success".green().to_string(),
        Status::Skipped(_) => "Skipped".yellow().to_string(),
        Status::Error(_) => "Error".red().to_string(),
    };
    let mut s = format!(
        "[{}] {} -> {}\n{} -> {} {}\n",
        label,
        result.input.display(),
        result.output.display(),
        format_size(result.original_size),
        format_size(result.compressed_size),
        format_diff(result.original_size, result.compressed_size)
    );
    match &result.status {
        Status::Success => {}
        Status::Skipped(msg) => s.push_str(&format!("{}\n", msg.yellow())),
        Status::Error(msg) => s.push_str(&format!("{}\n", msg.red())),
    }
    s
}

pub fn format_summary(results: &[FileResult]) -> String {
    let mut success = 0usize;
    let mut skipped = 0usize;
    let mut errors = 0usize;
    let mut total_in = 0u64;
    let mut total_out = 0u64;
    for r in results {
        match r.status {
            Status::Success => success += 1,
            Status::Skipped(_) => skipped += 1,
            Status::Error(_) => errors += 1,
        }
        total_in += r.original_size;
        total_out += r.compressed_size;
    }
    format!(
        "Compressed {} files ({} success, {} skipped, {} errors)\n{} -> {} {}\n",
        results.len(),
        success.to_string().green(),
        skipped.to_string().yellow(),
        errors.to_string().red(),
        format_size(total_in),
        format_size(total_out),
        format_diff(total_in, total_out)
    )
}
