//! Per-file processing pipeline: output path resolution, overwrite policy,
//! compression, savings checks and writing.

use std::fs;
use std::path::{Path, PathBuf};

use crate::bytesize::format_size;
use crate::cli::{Args, MinSavings, OutputFormat, OverwritePolicy};
use crate::compress;
use crate::output::{FileResult, Status};

fn output_file_name(input: &Path, args: &Args) -> PathBuf {
    let stem = input
        .file_stem()
        .map(|s| s.to_os_string())
        .unwrap_or_default();
    let ext: Option<String> = match args.format {
        OutputFormat::Original => input
            .extension()
            .map(|e| e.to_string_lossy().into_owned()),
        OutputFormat::Jpeg => Some("jpg".to_string()),
        OutputFormat::Png => Some("png".to_string()),
        OutputFormat::Gif => Some("gif".to_string()),
        OutputFormat::WebP => Some("webp".to_string()),
        OutputFormat::Tiff => Some("tiff".to_string()),
    };
    let mut name = stem;
    if let Some(suffix) = &args.suffix {
        name.push(suffix);
    }
    if let Some(ext) = ext {
        name.push(".");
        name.push(ext);
    }
    PathBuf::from(name)
}

fn compute_output_path(input: &Path, args: &Args, base: &Path) -> Result<PathBuf, ()> {
    let file_name = output_file_name(input, args);
    let out_dir: PathBuf = if args.keep_structure {
        let parent = input.parent().ok_or(())?;
        let abs_parent = std::path::absolute(parent).map_err(|_| ())?;
        let rel = abs_parent.strip_prefix(base).map_err(|_| ())?.to_path_buf();
        let root = if args.same_folder_as_input {
            base.to_path_buf()
        } else {
            args.output.clone().unwrap_or_default()
