        let (w, h) = (self.width, self.height);
        self.transform(h, w, |x, y| (w - 1 - y, x))
    }

    pub fn flip_horizontal(&self) -> Image {
        let (w, h) = (self.width, self.height);
        self.transform(w, h, |x, y| (w - 1 - x, y))
    }

    pub fn flip_vertical(&self) -> Image {
        let (w, h) = (self.width, self.height);
        self.transform(w, h, |x, y| (x, h - 1 - y))
    }

    /// Applies an EXIF orientation value (1..=8) so that the image is
    /// displayed upright.
    pub fn apply_orientation(&self, orientation: u16) -> Image {
        match orientation {
            2 => self.flip_horizontal(),
            3 => self.rotate180(),
            4 => self.flip_vertical(),
            5 => self.rotate90().flip_horizontal(),
            6 => self.rotate90(),
            7 => self.rotate270().flip_horizontal(),
            8 => self.rotate270(),
            _ => self.clone(),
        }
    }
}

fn lanczos3(x: f32) -> f32 {
    if x == 0.0 {
        return 1.0;
    }
    if x.abs() >= 3.0 {
        return 0.0;
    }
    let pix = std::f32::consts::PI * x;
    3.0 * pix.sin() * (pix / 3.0).sin() / (pix * pix)
}

struct Weights {
    start: usize,
    weights: Vec<f32>,
}

fn compute_weights(src_len: u32, dst_len: u32) -> Vec<Weights> {
    let scale = src_len as f32 / dst_len as f32;
    let support = if scale > 1.0 { 3.0 * scale } else { 3.0 };
    let mut result = Vec::with_capacity(dst_len as usize);
    for i in 0..dst_len {
        let center = (i as f32 + 0.5) * scale;
        let left = ((center - support).floor().max(0.0)) as usize;
        let right = ((center + support).ceil().min(src_len as f32)) as usize;
        let right = right.max(left + 1);
        let mut weights = Vec::with_capacity(right - left);
        let mut sum = 0.0f32;
        for j in left..right {
            let w = if scale > 1.0 {
                lanczos3((j as f32 + 0.5 - center) / scale)
            } else {
                lanczos3(j as f32 + 0.5 - center)
            };
            weights.push(w);
            sum += w;
        }
        if sum != 0.0 {
            for w in &mut weights {
                *w /= sum;
            }
        }
        result.push(Weights {
            start: left,
            weights,
        });
    }
    result
}

/// Resizes the image to the given dimensions using a Lanczos3 filter.
pub fn resize(img: &Image, new_w: u32, new_h: u32) -> Image {
    let new_w = new_w.max(1);
    let new_h = new_h.max(1);
    if new_w == img.width && new_h == img.height {
        return img.clone();
    }
    let sw = img.width as usize;
    let sh = img.height as usize;
    // Horizontal pass -> f32 buffer of new_w x sh
    let xw = compute_weights(img.width, new_w);
    let mut tmp = vec![0f32; new_w as usize * sh * 4];
    for y in 0..sh {
        let row = &img.data[y * sw * 4..(y + 1) * sw * 4];
        for (x, w) in xw.iter().enumerate() {
            let mut acc = [0f32; 4];
            for (k, wt) in w.weights.iter().enumerate() {
                let si = (w.start + k) * 4;
                acc[0] += row[si] as f32 * wt;
                acc[1] += row[si + 1] as f32 * wt;
                acc[2] += row[si + 2] as f32 * wt;
                acc[3] += row[si + 3] as f32 * wt;
            }
            let di = (y * new_w as usize + x) * 4;
            tmp[di..di + 4].copy_from_slice(&acc);
        }
    }
    // Vertical pass
    let yw = compute_weights(img.height, new_h);
    let mut out = Image::new(new_w, new_h);
    let nw = new_w as usize;
    for (y, w) in yw.iter().enumerate() {
        for x in 0..nw {
            let mut acc = [0f32; 4];
            for (k, wt) in w.weights.iter().enumerate() {
                let si = ((w.start + k) * nw + x) * 4;
                acc[0] += tmp[si] * wt;
                acc[1] += tmp[si + 1] * wt;
                acc[2] += tmp[si + 2] * wt;
                acc[3] += tmp[si + 3] * wt;
            }
            let di = (y * nw + x) * 4;
            for c in 0..4 {
                out.data[di + c] = acc[c].round().clamp(0.0, 255.0) as u8;
            }
        }
    }
    out
}
