//! Thin wrappers around the deflate implementation.

use std::io::{Read, Write};

use flate2::read::ZlibDecoder;
use flate2::write::ZlibEncoder;
use flate2::Compression;

pub fn zlib_compress(data: &[u8], level: u32) -> Vec<u8> {
    let mut enc = ZlibEncoder::new(Vec::with_capacity(data.len() / 2 + 64), Compression::new(level.min(9)));
    enc.write_all(data).expect("in-memory write");
    enc.finish().expect("in-memory finish")
}

pub fn zlib_decompress(data: &[u8], expected: usize) -> Result<Vec<u8>, String> {
    let mut dec = ZlibDecoder::new(data);
    let mut out = Vec::with_capacity(expected);
    match dec.read_to_end(&mut out) {
        Ok(_) => Ok(out),
        Err(e) => {
            let msg = e.to_string();
            if msg.contains("corrupt") || msg.contains("invalid") {
                Err("corrupt deflate stream".to_string())
            } else if msg.contains("unexpected end") || msg.contains("failed to fill") {
                Err("unexpected end of deflate stream".to_string())
            } else {
                Err(msg)
            }
        }
    }
}
