//! PNG decoding and encoding.

use crate::codecs::deflate::{zlib_compress, zlib_decompress};
use crate::image::Image;

const SIGNATURE: [u8; 8] = [0x89, b'P', b'N', b'G', b'\r', b'\n', 0x1a, b'\n'];

#[derive(Debug, Clone)]
pub struct Chunk {
    pub kind: [u8; 4],
    pub data: Vec<u8>,
}

#[derive(Debug, Clone)]
pub struct Png {
    pub width: u32,
    pub height: u32,
    pub bit_depth: u8,
    pub color_type: u8,
    pub interlace: u8,
    pub palette: Vec<[u8; 3]>,
    pub trns: Option<Vec<u8>>,
    /// Unfiltered, non interlaced scanlines (no filter byte).
    pub raw: Vec<u8>,
    /// Ancillary chunks found before IDAT (in order).
    pub before_idat: Vec<Chunk>,
    /// Ancillary chunks found after IDAT (in order).
    pub after_idat: Vec<Chunk>,
}

fn be32(b: &[u8]) -> u32 {
    u32::from_be_bytes([b[0], b[1], b[2], b[3]])
}

pub fn channels(color_type: u8) -> usize {
    match color_type {
        0 => 1,
        2 => 3,
        3 => 1,
        4 => 2,
        6 => 4,
        _ => 1,
    }
}

fn bits_per_pixel(color_type: u8, bit_depth: u8) -> usize {
    channels(color_type) * bit_depth as usize
}

fn row_bytes(width: u32, color_type: u8, bit_depth: u8) -> usize {
    (width as usize * bits_per_pixel(color_type, bit_depth) + 7) / 8
}

fn paeth(a: u8, b: u8, c: u8) -> u8 {
    let p = a as i16 + b as i16 - c as i16;
    let pa = (p - a as i16).abs();
    let pb = (p - b as i16).abs();
    let pc = (p - c as i16).abs();
    if pa <= pb && pa <= pc {
        a
    } else if pb <= pc {
        b
    } else {
        c
    }
}

fn unfilter_row(filter: u8, row: &mut [u8], prev: &[u8], bpp: usize) -> Result<(), String> {
    let n = row.len();
    match filter {
        0 => {}
        1 => {
            for i in bpp..n {
                row[i] = row[i].wrapping_add(row[i - bpp]);
            }
        }
        2 => {
            for i in 0..n {
                row[i] = row[i].wrapping_add(prev[i]);
            }
        }
        3 => {
            for i in 0..n {
                let a = if i >= bpp { row[i - bpp] as u16 } else { 0 };
                let b = prev[i] as u16;
                row[i] = row[i].wrapping_add(((a + b) / 2) as u8);
            }
        }
        4 => {
            for i in 0..n {
                let a = if i >= bpp { row[i - bpp] } else { 0 };
                let b = prev[i];
                let c = if i >= bpp { prev[i - bpp] } else { 0 };
                row[i] = row[i].wrapping_add(paeth(a, b, c));
            }
        }
        _ => return Err(format!("invalid filter method {}", filter)),
    }
    Ok(())
}

/// Adam7 pass parameters: (x start, y start, x step, y step)
const ADAM7: [(usize, usize, usize, usize); 7] = [
    (0, 0, 8, 8),
    (4, 0, 8, 8),
    (0, 4, 4, 8),
    (2, 0, 4, 4),
    (0, 2, 2, 4),
    (1, 0, 2, 2),
    (0, 1, 1, 2),
];

fn get_bits(row: &[u8], index: usize, bits: usize) -> u8 {
    match bits {
        8 => row[index],
        16 => row[index * 2],
        1 | 2 | 4 => {
            let per_byte = 8 / bits;
            let byte = row[index / per_byte];
            let shift = 8 - bits * (index % per_byte + 1);
            (byte >> shift) & ((1u8 << bits) - 1)
        }
        _ => 0,
    }
}

fn set_bits(row: &mut [u8], index: usize, bits: usize, value: u8) {
    match bits {
        8 => row[index] = value,
        1 | 2 | 4 => {
            let per_byte = 8 / bits;
            let shift = 8 - bits * (index % per_byte + 1);
            let mask = ((1u8 << bits) - 1) << shift;
            let b = &mut row[index / per_byte];
            *b = (*b & !mask) | ((value << shift) & mask);
        }
        _ => {}
    }
}

pub fn decode(data: &[u8]) -> Result<Png, String> {
    if data.len() < 8 || data[..8] != SIGNATURE {
        return Err("Invalid PNG signature".to_string());
    }
    let mut pos = 8usize;
    let mut first = true;
    let mut png: Option<Png> = None;
    let mut idat = Vec::new();
    let mut seen_idat = false;
    let mut seen_iend = false;
    while pos < data.len() && !seen_iend {
        if pos + 8 > data.len() {
            return Err("unexpected end of file".to_string());
        }
        let len = be32(&data[pos..pos + 4]) as usize;
        let kind: [u8; 4] = [data[pos + 4], data[pos + 5], data[pos + 6], data[pos + 7]];
        if pos + 12 + len > data.len() {
            return Err("unexpected end of file".to_string());
        }
        let body = &data[pos + 8..pos + 8 + len];
        let crc = be32(&data[pos + 8 + len..pos + 12 + len]);
        let mut hasher = crc32fast::Hasher::new();
        hasher.update(&kind);
        hasher.update(body);
        if hasher.finalize() != crc {
            return Err("invalid CRC encountered (checking CRC can be disabled)".to_string());
        }
        pos += 12 + len;
        if first {
            if &kind != b"IHDR" {
                return Err("first chunk is not the header chunk".to_string());
            }
            first = false;
            if body.len() != 13 {
                return Err("invalid IHDR length".to_string());
            }
            let width = be32(&body[0..4]);
            let height = be32(&body[4..8]);
            let bit_depth = body[8];
            let color_type = body[9];
            let interlace = body[12];
            if width == 0 || height == 0 {
                return Err("invalid image dimensions".to_string());
            }
            let valid = match color_type {
                0 => matches!(bit_depth, 1 | 2 | 4 | 8 | 16),
                2 | 4 | 6 => matches!(bit_depth, 8 | 16),
                3 => matches!(bit_depth, 1 | 2 | 4 | 8),
                _ => false,
            };
            if !valid {
                return Err(format!(
                    "invalid color type / bit depth combination ({}, {})",
                    color_type, bit_depth
                ));
            }
            if body[10] != 0 || body[11] != 0 || interlace > 1 {
                return Err("unsupported compression, filter or interlace method".to_string());
            }
            png = Some(Png {
                width,
                height,
                bit_depth,
                color_type,
                interlace,
                palette: Vec::new(),
                trns: None,
                raw: Vec::new(),
                before_idat: Vec::new(),
                after_idat: Vec::new(),
            });
            continue;
        }
        let p = png.as_mut().unwrap();
        match &kind {
            b"PLTE" => {
                if body.len() % 3 != 0 || body.is_empty() {
                    return Err("invalid palette length".to_string());
                }
                p.palette = body.chunks_exact(3).map(|c| [c[0], c[1], c[2]]).collect();
            }
            b"tRNS" => p.trns = Some(body.to_vec()),
            b"IDAT" => {
                seen_idat = true;
                idat.extend_from_slice(body);
            }
            b"IEND" => seen_iend = true,
            b"IHDR" => return Err("duplicate IHDR chunk".to_string()),
            _ => {
                let chunk = Chunk {
                    kind,
                    data: body.to_vec(),
                };
                if seen_idat {
                    p.after_idat.push(chunk);
                } else {
                    p.before_idat.push(chunk);
                }
            }
        }
    }
    let mut p = png.ok_or_else(|| "first chunk is not the header chunk".to_string())?;
    if !seen_idat {
        return Err("IDAT chunk missing".to_string());
    }
    if p.color_type == 3 && p.palette.is_empty() {
        return Err("palette not found".to_string());
    }
    let w = p.width as usize;
    let h = p.height as usize;
    let bpp = (bits_per_pixel(p.color_type, p.bit_depth) + 7) / 8;
    let stride = row_bytes(p.width, p.color_type, p.bit_depth);
    let expected = if p.interlace == 0 {
        (stride + 1) * h
    } else {
        ADAM7
            .iter()
            .map(|&(xs, ys, xstep, ystep)| {
                let pw = if w > xs { (w - xs + xstep - 1) / xstep } else { 0 };
                let ph = if h > ys { (h - ys + ystep - 1) / ystep } else { 0 };
                if pw == 0 || ph == 0 {
                    0
                } else {
                    (row_bytes(pw as u32, p.color_type, p.bit_depth) + 1) * ph
                }
            })
            .sum()
    };
    let inflated = zlib_decompress(&idat, expected)?;
    if inflated.len() < expected {
        return Err("not enough image data".to_string());
    }
    let mut raw = vec![0u8; stride * h];
    if p.interlace == 0 {
        let mut prev = vec![0u8; stride];
        for y in 0..h {
            let src = &inflated[y * (stride + 1)..(y + 1) * (stride + 1)];
            let filter = src[0];
            let row = &mut raw[y * stride..(y + 1) * stride];
            row.copy_from_slice(&src[1..]);
            unfilter_row(filter, row, &prev, bpp)?;
            prev.copy_from_slice(row);
        }
    } else {
        let bits = bits_per_pixel(p.color_type, p.bit_depth);
        let mut off = 0usize;
        for &(xs, ys, xstep, ystep) in ADAM7.iter() {
            let pw = if w > xs { (w - xs + xstep - 1) / xstep } else { 0 };
            let ph = if h > ys { (h - ys + ystep - 1) / ystep } else { 0 };
            if pw == 0 || ph == 0 {
                continue;
            }
            let pstride = row_bytes(pw as u32, p.color_type, p.bit_depth);
            let mut prev = vec![0u8; pstride];
            let mut row = vec![0u8; pstride];
            for py in 0..ph {
                let src = &inflated[off..off + pstride + 1];
                off += pstride + 1;
                row.copy_from_slice(&src[1..]);
                unfilter_row(src[0], &mut row, &prev, bpp)?;
                prev.copy_from_slice(&row);
                let y = ys + py * ystep;
                let dst = &mut raw[y * stride..(y + 1) * stride];
                if bits >= 8 {
                    let nb = bits / 8;
                    for px in 0..pw {
                        let x = xs + px * xstep;
                        dst[x * nb..(x + 1) * nb].copy_from_slice(&row[px * nb..(px + 1) * nb]);
                    }
                } else {
                    for px in 0..pw {
                        let x = xs + px * xstep;
                        let v = get_bits(&row, px, bits);
                        set_bits(dst, x, bits, v);
                    }
                }
            }
        }
    }
    p.raw = raw;
    Ok(p)
}

/// Converts decoded PNG data into an RGBA8 image.
pub fn to_image(p: &Png) -> Image {
    let w = p.width as usize;
    let h = p.height as usize;
    let stride = row_bytes(p.width, p.color_type, p.bit_depth);
    let mut out = vec![0u8; w * h * 4];
    let bd = p.bit_depth as usize;
    let max = ((1u32 << bd) - 1) as u32;
    let trns = p.trns.as_deref();
    for y in 0..h {
        let row = &p.raw[y * stride..(y + 1) * stride];
        for x in 0..w {
            let o = (y * w + x) * 4;
            match p.color_type {
                0 => {
                    let v = if bd == 16 {
                        u16::from_be_bytes([row[x * 2], row[x * 2 + 1]]) as u32
                    } else {
                        get_bits(row, x, bd) as u32
                    };
                    let g = if bd == 16 { (v >> 8) as u8 } else { ((v * 255) / max) as u8 };
                    let mut a = 255u8;
                    if let Some(t) = trns {
                        if t.len() >= 2 && u16::from_be_bytes([t[0], t[1]]) as u32 == v {
                            a = 0;
                        }
                    }
                    out[o] = g;
                    out[o + 1] = g;
                    out[o + 2] = g;
                    out[o + 3] = a;
                }
                2 => {
                    let (r, g, b, raw3) = if bd == 16 {
                        let i = x * 6;
                        let r16 = u16::from_be_bytes([row[i], row[i + 1]]);
                        let g16 = u16::from_be_bytes([row[i + 2], row[i + 3]]);
                        let b16 = u16::from_be_bytes([row[i + 4], row[i + 5]]);
                        ((r16 >> 8) as u8, (g16 >> 8) as u8, (b16 >> 8) as u8, [r16, g16, b16])
                    } else {
                        let i = x * 3;
                        (row[i], row[i + 1], row[i + 2], [row[i] as u16, row[i + 1] as u16, row[i + 2] as u16])
                    };
                    let mut a = 255u8;
                    if let Some(t) = trns {
                        if t.len() >= 6 {
                            let tr = u16::from_be_bytes([t[0], t[1]]);
                            let tg = u16::from_be_bytes([t[2], t[3]]);
                            let tb = u16::from_be_bytes([t[4], t[5]]);
                            if [tr, tg, tb] == raw3 {
                                a = 0;
                            }
                        }
                    }
                    out[o] = r;
                    out[o + 1] = g;
                    out[o + 2] = b;
                    out[o + 3] = a;
                }
                3 => {
                    let idx = get_bits(row, x, bd) as usize;
                    let c = p.palette.get(idx).copied().unwrap_or([0, 0, 0]);
                    let a = trns.and_then(|t| t.get(idx).copied()).unwrap_or(255);
                    out[o] = c[0];
                    out[o + 1] = c[1];
                    out[o + 2] = c[2];
                    out[o + 3] = a;
                }
                4 => {
                    let (g, a) = if bd == 16 {
                        (row[x * 4], row[x * 4 + 2])
                    } else {
                        (row[x * 2], row[x * 2 + 1])
                    };
                    out[o] = g;
                    out[o + 1] = g;
                    out[o + 2] = g;
                    out[o + 3] = a;
                }
                6 => {
                    if bd == 16 {
                        let i = x * 8;
                        out[o] = row[i];
                        out[o + 1] = row[i + 2];
                        out[o + 2] = row[i + 4];
                        out[o + 3] = row[i + 6];
                    } else {
                        out[o..o + 4].copy_from_slice(&row[x * 4..x * 4 + 4]);
                    }
                }
                _ => {}
            }
        }
    }
    Image::from_rgba(p.width, p.height, out)
}

// ---------------------------------------------------------------------------
// Encoding
// ---------------------------------------------------------------------------

fn write_chunk(out: &mut Vec<u8>, kind: &[u8; 4], data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    out.extend_from_slice(kind);
    out.extend_from_slice(data);
    let mut hasher = crc32fast::Hasher::new();
    hasher.update(kind);
    hasher.update(data);
    out.extend_from_slice(&hasher.finalize().to_be_bytes());
}

fn filter_row(filter: u8, row: &[u8], prev: &[u8], bpp: usize, out: &mut [u8]) {
    let n = row.len();
    match filter {
        0 => out.copy_from_slice(row),
        1 => {
            for i in 0..n {
                let a = if i >= bpp { row[i - bpp] } else { 0 };
                out[i] = row[i].wrapping_sub(a);
            }
        }
        2 => {
            for i in 0..n {
                out[i] = row[i].wrapping_sub(prev[i]);
            }
        }
        3 => {
            for i in 0..n {
                let a = if i >= bpp { row[i - bpp] as u16 } else { 0 };
                let b = prev[i] as u16;
                out[i] = row[i].wrapping_sub(((a + b) / 2) as u8);
            }
        }
        _ => {
            for i in 0..n {
                let a = if i >= bpp { row[i - bpp] } else { 0 };
                let b = prev[i];
                let c = if i >= bpp { prev[i - bpp] } else { 0 };
                out[i] = row[i].wrapping_sub(paeth(a, b, c));
            }
        }
    }
}

fn row_cost(filtered: &[u8]) -> u64 {
    filtered.iter().map(|&b| (b as i8).unsigned_abs() as u64).sum()
}

/// Filter strategies tried for the image data.
#[derive(Clone, Copy)]
enum Strategy {
    Fixed(u8),
    MinSum,
}

fn filter_image(raw: &[u8], stride: usize, height: usize, bpp: usize, strategy: Strategy) -> Vec<u8> {
    let mut out = Vec::with_capacity((stride + 1) * height);
    let zero = vec![0u8; stride];
    let mut buf = vec![0u8; stride];
    let mut best = vec![0u8; stride];
    for y in 0..height {
        let row = &raw[y * stride..(y + 1) * stride];
        let prev = if y == 0 { &zero[..] } else { &raw[(y - 1) * stride..y * stride] };
        match strategy {
            Strategy::Fixed(f) => {
                filter_row(f, row, prev, bpp, &mut buf);
                out.push(f);
                out.extend_from_slice(&buf);
            }
            Strategy::MinSum => {
                let mut best_f = 0u8;
                let mut best_cost = u64::MAX;
                for f in 0..5u8 {
                    filter_row(f, row, prev, bpp, &mut buf);
                    let cost = row_cost(&buf);
                    if cost < best_cost {
                        best_cost = cost;
                        best_f = f;
                        best.copy_from_slice(&buf);
                    }
                }
                out.push(best_f);
                out.extend_from_slice(&best);
            }
        }
    }
    out
}

/// A fully specified PNG image ready to be written.
pub struct EncodeInput<'a> {
    pub width: u32,
    pub height: u32,
    pub bit_depth: u8,
    pub color_type: u8,
    pub palette: &'a [[u8; 3]],
    pub trns: Option<&'a [u8]>,
    pub raw: &'a [u8],
    pub before_idat: &'a [Chunk],
    pub after_idat: &'a [Chunk],
}

/// Compresses the image data trying several filter strategies and returns
/// the smallest IDAT payload.
fn best_idat(input: &EncodeInput, level: u8) -> Vec<u8> {
    let stride = row_bytes(input.width, input.color_type, input.bit_depth);
    let bpp = (bits_per_pixel(input.color_type, input.bit_depth) + 7) / 8;
    let h = input.height as usize;
    let mut strategies: Vec<Strategy> = vec![Strategy::MinSum];
    if level >= 2 {
        strategies.push(Strategy::Fixed(0));
        strategies.push(Strategy::Fixed(1));
        strategies.push(Strategy::Fixed(2));
        strategies.push(Strategy::Fixed(3));
        strategies.push(Strategy::Fixed(4));
    } else if level == 1 {
        strategies.push(Strategy::Fixed(0));
    }
    let zlevel = if level == 0 { 6 } else { 9 };
    let mut best: Option<Vec<u8>> = None;
    for s in strategies {
        let filtered = filter_image(input.raw, stride, h, bpp, s);
        let compressed = zlib_compress(&filtered, zlevel);
        if best.as_ref().map(|b| compressed.len() < b.len()).unwrap_or(true) {
            best = Some(compressed);
        }
    }
    best.unwrap_or_default()
}

pub fn encode(input: &EncodeInput, level: u8) -> Vec<u8> {
    let idat = best_idat(input, level);
    let mut out = Vec::with_capacity(idat.len() + 1024);
    out.extend_from_slice(&SIGNATURE);
    let mut ihdr = Vec::with_capacity(13);
    ihdr.extend_from_slice(&input.width.to_be_bytes());
    ihdr.extend_from_slice(&input.height.to_be_bytes());
    ihdr.push(input.bit_depth);
    ihdr.push(input.color_type);
    ihdr.push(0);
    ihdr.push(0);
    ihdr.push(0);
    write_chunk(&mut out, b"IHDR", &ihdr);
    for c in input.before_idat {
        write_chunk(&mut out, &c.kind, &c.data);
    }
    if input.color_type == 3 {
        let mut plte = Vec::with_capacity(input.palette.len() * 3);
        for c in input.palette {
            plte.extend_from_slice(c);
        }
        write_chunk(&mut out, b"PLTE", &plte);
    }
    if let Some(t) = input.trns {
        if !t.is_empty() {
            write_chunk(&mut out, b"tRNS", t);
        }
    }
    write_chunk(&mut out, b"IDAT", &idat);
    for c in input.after_idat {
        write_chunk(&mut out, &c.kind, &c.data);
    }
    write_chunk(&mut out, b"IEND", &[]);
    out
}

/// Candidate representation of an 8-bit image.
struct Candidate {
    bit_depth: u8,
    color_type: u8,
    palette: Vec<[u8; 3]>,
    trns: Option<Vec<u8>>,
    raw: Vec<u8>,
}

fn pack_indices(indices: &[u8], width: usize, height: usize, bits: usize) -> Vec<u8> {
    let stride = (width * bits + 7) / 8;
    let mut raw = vec![0u8; stride * height];
    for y in 0..height {
        let row = &mut raw[y * stride..(y + 1) * stride];
        for x in 0..width {
            set_bits(row, x, bits, indices[y * width + x]);
        }
    }
    raw
}

/// Builds the smallest lossless representations of an RGBA8 image.
fn candidates_from_rgba(img: &Image) -> Vec<Candidate> {
    let w = img.width as usize;
    let h = img.height as usize;
    let n = w * h;
    let has_alpha = img.has_alpha();
    let gray = img.is_gray();
    let mut cands = Vec::new();

    // Palette candidate (<= 256 distinct colors)
    let mut colors: Vec<[u8; 4]> = Vec::new();
    let mut map: std::collections::HashMap<[u8; 4], u8> = std::collections::HashMap::new();
    let mut indices = Vec::with_capacity(n);
    let mut too_many = false;
    for p in img.data.chunks_exact(4) {
        let key = [p[0], p[1], p[2], p[3]];
        let idx = match map.get(&key) {
            Some(&i) => i,
            None => {
                if colors.len() >= 256 {
                    too_many = true;
                    break;
                }
                let i = colors.len() as u8;
                colors.push(key);
                map.insert(key, i);
                i
            }
        };
        indices.push(idx);
    }
    if !too_many {
        // Sort palette: transparent entries first so tRNS can be truncated.
        let mut order: Vec<usize> = (0..colors.len()).collect();
        order.sort_by_key(|&i| (colors[i][3], colors[i][0], colors[i][1], colors[i][2]));
        let mut remap = vec![0u8; colors.len()];
        for (new_i, &old_i) in order.iter().enumerate() {
            remap[old_i] = new_i as u8;
        }
        let sorted: Vec<[u8; 4]> = order.iter().map(|&i| colors[i]).collect();
        let indices: Vec<u8> = indices.iter().map(|&i| remap[i as usize]).collect();
        let palette: Vec<[u8; 3]> = sorted.iter().map(|c| [c[0], c[1], c[2]]).collect();
        let mut trns: Vec<u8> = sorted.iter().map(|c| c[3]).collect();
        while trns.last() == Some(&255) {
            trns.pop();
        }
        let bits = if sorted.len() <= 2 {
            1
        } else if sorted.len() <= 4 {
            2
        } else if sorted.len() <= 16 {
            4
        } else {
            8
        };
        let raw = pack_indices(&indices, w, h, bits);
        cands.push(Candidate {
            bit_depth: bits as u8,
            color_type: 3,
            palette,
            trns: if trns.is_empty() { None } else { Some(trns) },
            raw,
        });
    }

    if gray {
        if has_alpha {
            let mut raw = Vec::with_capacity(n * 2);
            for p in img.data.chunks_exact(4) {
                raw.push(p[0]);
                raw.push(p[3]);
            }
            cands.push(Candidate {
                bit_depth: 8,
                color_type: 4,
                palette: Vec::new(),
                trns: None,
                raw,
            });
        } else {
            let values: Vec<u8> = img.data.chunks_exact(4).map(|p| p[0]).collect();
            let bits = if values.iter().all(|&v| v == 0 || v == 255) {
                1
            } else if values.iter().all(|&v| v % 85 == 0) {
                2
            } else if values.iter().all(|&v| v % 17 == 0) {
                4
            } else {
                8
            };
            let raw = if bits == 8 {
                values
            } else {
                let div = 255 / ((1u16 << bits) - 1) as u8;
                let scaled: Vec<u8> = values.iter().map(|&v| v / div).collect();
                pack_indices(&scaled, w, h, bits)
            };
            cands.push(Candidate {
                bit_depth: bits as u8,
                color_type: 0,
                palette: Vec::new(),
                trns: None,
                raw,
            });
        }
    } else if has_alpha {
        cands.push(Candidate {
            bit_depth: 8,
            color_type: 6,
            palette: Vec::new(),
            trns: None,
            raw: img.data.clone(),
        });
    } else {
        cands.push(Candidate {
            bit_depth: 8,
            color_type: 2,
            palette: Vec::new(),
            trns: None,
            raw: img.to_rgb(),
        });
    }
    cands
}

/// Chunks that remain valid regardless of the chosen color representation.
fn keep_chunk(kind: &[u8; 4]) -> bool {
    matches!(
        kind,
        b"tEXt" | b"zTXt" | b"iTXt" | b"eXIf" | b"pHYs" | b"iCCP" | b"sRGB" | b"gAMA" | b"cHRM" | b"tIME"
    )
}

/// Encodes an RGBA8 image losslessly, choosing the smallest representation.
pub fn encode_rgba_lossless(img: &Image, level: u8, before: &[Chunk], after: &[Chunk]) -> Vec<u8> {
    let cands = candidates_from_rgba(img);
    let before: Vec<Chunk> = before.iter().filter(|c| keep_chunk(&c.kind)).cloned().collect();
    let after: Vec<Chunk> = after.iter().filter(|c| keep_chunk(&c.kind)).cloned().collect();
    let mut best: Option<Vec<u8>> = None;
    for c in &cands {
        let input = EncodeInput {
            width: img.width,
            height: img.height,
            bit_depth: c.bit_depth,
            color_type: c.color_type,
            palette: &c.palette,
            trns: c.trns.as_deref(),
            raw: &c.raw,
            before_idat: &before,
            after_idat: &after,
        };
        let enc = encode(&input, level);
        if best.as_ref().map(|b| enc.len() < b.len()).unwrap_or(true) {
            best = Some(enc);
        }
    }
    best.unwrap_or_default()
}

/// Returns true when every 16-bit sample can be represented with 8 bits.
fn reducible_16(p: &Png) -> bool {
    p.raw.chunks_exact(2).all(|c| c[0] == c[1])
}

/// Lossless optimization of an existing PNG file. Returns the original data
/// when no smaller representation could be found.
pub fn optimize_lossless(data: &[u8], level: u8) -> Result<Vec<u8>, String> {
    let png = decode(data)?;
    let before: Vec<Chunk> = png.before_idat.iter().filter(|c| keep_chunk(&c.kind)).cloned().collect();
    let after: Vec<Chunk> = png.after_idat.iter().filter(|c| keep_chunk(&c.kind)).cloned().collect();
    let result = if png.bit_depth == 16 && !reducible_16(&png) {
        let input = EncodeInput {
            width: png.width,
            height: png.height,
            bit_depth: 16,
            color_type: png.color_type,
            palette: &png.palette,
            trns: png.trns.as_deref(),
            raw: &png.raw,
            before_idat: &before,
            after_idat: &after,
        };
        encode(&input, level)
    } else {
        let img = to_image(&png);
        encode_rgba_lossless(&img, level, &before, &after)
    };
    if result.len() < data.len() {
        Ok(result)
    } else {
        Ok(data.to_vec())
    }
}

/// Encodes an indexed image (palette with alpha) as PNG, applying the usual
/// reductions (bit depth, grayscale, ...).
pub fn encode_indexed(width: u32, height: u32, indices: &[u8], palette: &[[u8; 4]], level: u8, before: &[Chunk], after: &[Chunk]) -> Vec<u8> {
    // Expand to RGBA and let the lossless encoder choose the representation;
    // the palette has at most 256 entries so a palette candidate always exists.
    let mut data = Vec::with_capacity(indices.len() * 4);
    for &i in indices {
        let c = palette.get(i as usize).copied().unwrap_or([0, 0, 0, 255]);
        data.extend_from_slice(&c);
    }
    let img = Image::from_rgba(width, height, data);
    encode_rgba_lossless(&img, level, before, after)
}
