//! Color quantization (median cut) used for lossy PNG/GIF output.

use std::collections::HashMap;

use crate::image::Image;

pub struct Quantized {
    pub palette: Vec<[u8; 4]>,
    pub indices: Vec<u8>,
}

#[derive(Clone)]
struct Entry {
    color: [u8; 4],
    count: u32,
}

struct Box {
    entries: Vec<Entry>,
    count: u64,
    /// Sum of squared deviations from the mean (over all channels), weighted.
    error: f64,
    min: [u8; 4],
    max: [u8; 4],
}

impl Box {
    fn new(entries: Vec<Entry>) -> Box {
        let mut min = [255u8; 4];
        let mut max = [0u8; 4];
        let mut count = 0u64;
        let mut sum = [0f64; 4];
        for e in &entries {
            for c in 0..4 {
                min[c] = min[c].min(e.color[c]);
                max[c] = max[c].max(e.color[c]);
                sum[c] += e.color[c] as f64 * e.count as f64;
            }
            count += e.count as u64;
        }
        let mut error = 0.0;
        if count > 0 {
            let mean = [
                sum[0] / count as f64,
                sum[1] / count as f64,
                sum[2] / count as f64,
                sum[3] / count as f64,
            ];
            for e in &entries {
                let mut d = 0.0;
                for c in 0..4 {
                    let diff = e.color[c] as f64 - mean[c];
                    d += diff * diff;
                }
                error += d * e.count as f64;
            }
        }
        Box {
            entries,
            count,
            error,
            min,
            max,
        }
    }

    fn mean_color(&self) -> [u8; 4] {
        if self.count == 0 {
            return [0, 0, 0, 255];
        }
        let mut sum = [0f64; 4];
        for e in &self.entries {
            for c in 0..4 {
                sum[c] += e.color[c] as f64 * e.count as f64;
            }
        }
        let mut out = [0u8; 4];
        for c in 0..4 {
            out[c] = (sum[c] / self.count as f64).round().clamp(0.0, 255.0) as u8;
        }
        out
    }

    fn can_split(&self) -> bool {
        self.entries.len() > 1
    }

    fn split(mut self) -> (Box, Box) {
        // Choose channel with the largest range (alpha weighted a bit less).
        let mut best_c = 0;
        let mut best_range = -1i32;
        for c in 0..4 {
            let mut range = self.max[c] as i32 - self.min[c] as i32;
            if c == 3 {
                range = range * 3 / 4;
            }
            if range > best_range {
                best_range = range;
                best_c = c;
            }
        }
        self.entries.sort_by_key(|e| e.color[best_c]);
        let half = self.count / 2;
        let mut acc = 0u64;
        let mut split_at = 0usize;
        for (i, e) in self.entries.iter().enumerate() {
            acc += e.count as u64;
            if acc >= half {
                split_at = i + 1;
                break;
            }
        }
        if split_at >= self.entries.len() {
            split_at = self.entries.len() - 1;
        }
        if split_at == 0 {
            split_at = 1;
        }
        let right = self.entries.split_off(split_at);
        (Box::new(self.entries), Box::new(right))
    }
}

fn target_mse(quality: u32) -> f64 {
    if quality >= 100 {
        return 0.0;
    }
    let rms = (100 - quality) as f64 * 0.5;
    rms * rms * 3.0
}

fn key_of(c: &[u8], reduced: bool) -> u32 {
    if reduced {
        let r = (c[0] >> 2) as u32;
        let g = (c[1] >> 2) as u32;
        let b = (c[2] >> 2) as u32;
        let a = (c[3] >> 2) as u32;
        (r << 18) | (g << 12) | (b << 6) | a
    } else {
        u32::from_be_bytes([c[0], c[1], c[2], c[3]])
    }
}

fn histogram(img: &Image) -> (Vec<Entry>, bool) {
    let mut map: HashMap<u32, (u32, [u64; 4])> = HashMap::new();
    let mut reduced = false;
    for p in img.data.chunks_exact(4) {
        let k = key_of(p, false);
        let e = map.entry(k).or_insert((0, [0; 4]));
        e.0 += 1;
        if map.len() > 65536 {
            reduced = true;
            break;
        }
    }
    if reduced {
        map.clear();
        for p in img.data.chunks_exact(4) {
            let k = key_of(p, true);
            let e = map.entry(k).or_insert((0, [0; 4]));
            e.0 += 1;
            for c in 0..4 {
                e.1[c] += p[c] as u64;
            }
        }
        let entries = map
            .into_iter()
            .map(|(_, (count, sums))| {
                let mut color = [0u8; 4];
                for c in 0..4 {
                    color[c] = (sums[c] / count as u64) as u8;
                }
                Entry { color, count }
            })
            .collect();
