                }
                Entry { color, count }
            })
            .collect();
        (entries, true)
    } else {
        let entries = map
            .into_iter()
            .map(|(k, (count, _))| Entry {
                color: k.to_be_bytes(),
                count,
            })
            .collect();
        (entries, false)
    }
}

fn nearest(palette: &[[u8; 4]], c: &[u8]) -> u8 {
    let mut best = 0usize;
