        let d = (dr * dr + dg * dg + db * db + da * da) as u32;
        if d < best_d {
            best_d = d;
            best = i;
            if d == 0 {
                break;
            }
        }
    }
    best as u8
}

/// Quantizes the image to at most `max_colors` colors, using `quality`
/// (0-100) to decide how many colors are actually needed.
pub fn quantize(img: &Image, quality: u32, max_colors: usize) -> Quantized {
