    #[test]
    fn fdct_matches_reference() {
        let mut samples = [0u8; 64];
        for (i, s) in samples.iter_mut().enumerate() {
            *s = ((i * 37 + 11) % 256) as u8;
        }
        let q = [1u16; 64];
        let div = divisors(&q);
