//! JPEG encoder: baseline or progressive, with optimized Huffman tables.

use crate::codecs::jpeg::{Component, Marker, ZIGZAG};
use crate::image::Image;

/// Quantization table family.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QuantTables {
    /// Tables tuned for perceptual quality (identical for luma and chroma).
    Perceptual,
    /// Classic JPEG Annex K tables.
    AnnexK,
}

const PERCEPTUAL_TABLE: [u16; 64] = [
    16, 16, 16, 18, 25, 37, 56, 85, 16, 17, 20, 27, 34, 40, 53, 75, 16, 20, 24, 31, 43, 62, 91,
    135, 18, 27, 31, 40, 53, 74, 106, 156, 25, 34, 43, 53, 69, 94, 131, 189, 37, 40, 62, 74, 94,
    124, 169, 238, 56, 53, 91, 106, 131, 169, 226, 311, 85, 75, 135, 156, 189, 238, 311, 418,
];

const ANNEX_K_LUMA: [u16; 64] = [
    16, 11, 10, 16, 24, 40, 51, 61, 12, 12, 14, 19, 26, 58, 60, 55, 14, 13, 16, 24, 40, 57, 69,
    56, 14, 17, 22, 29, 51, 87, 80, 62, 18, 22, 37, 56, 68, 109, 103, 77, 24, 35, 55, 64, 81, 104,
    113, 92, 49, 64, 78, 87, 103, 121, 120, 101, 72, 92, 95, 98, 112, 100, 103, 99,
];

const ANNEX_K_CHROMA: [u16; 64] = [
    17, 18, 24, 47, 99, 99, 99, 99, 18, 21, 26, 66, 99, 99, 99, 99, 24, 26, 56, 99, 99, 99, 99,
    99, 47, 66, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99,
    99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99, 99,
];

pub fn quality_scaling(quality: u32) -> u32 {
    let q = quality.clamp(1, 100);
    if q < 50 {
        5000 / q
    } else {
        200 - q * 2
    }
}

pub fn scaled_table(base: &[u16; 64], quality: u32, force_baseline: bool) -> [u16; 64] {
    let scale = quality_scaling(quality);
    let mut out = [0u16; 64];
    for i in 0..64 {
        let mut v = (base[i] as u32 * scale + 50) / 100;
        if v == 0 {
            v = 1;
        }
        let max = if force_baseline { 255 } else { 32767 };
        if v > max {
            v = max;
        }
        out[i] = v as u16;
    }
    out
}

pub fn quant_tables(kind: QuantTables, quality: u32) -> Vec<[u16; 64]> {
    match kind {
        QuantTables::Perceptual => {
            let t = scaled_table(&PERCEPTUAL_TABLE, quality, false);
            vec![t, t]
        }
        QuantTables::AnnexK => vec![
            scaled_table(&ANNEX_K_LUMA, quality, true),
            scaled_table(&ANNEX_K_CHROMA, quality, true),
        ],
    }
}

// ---------------------------------------------------------------------------
// Forward DCT (AAN float)
// ---------------------------------------------------------------------------

const AAN_SCALE: [f32; 8] = [
    1.0, 1.387039845, 1.306562965, 1.175875602, 1.0, 0.785694958, 0.541196100, 0.275899379,
];

fn divisors(q: &[u16; 64]) -> [f32; 64] {
    let mut d = [0f32; 64];
    for row in 0..8 {
        for col in 0..8 {
            d[row * 8 + col] = 1.0 / (q[row * 8 + col] as f32 * AAN_SCALE[row] * AAN_SCALE[col] * 8.0);
        }
    }
    d
}

fn fdct_1d(d: &mut [f32; 8]) {
    let tmp0 = d[0] + d[7];
    let tmp7 = d[0] - d[7];
    let tmp1 = d[1] + d[6];
    let tmp6 = d[1] - d[6];
    let tmp2 = d[2] + d[5];
    let tmp5 = d[2] - d[5];
    let tmp3 = d[3] + d[4];
    let tmp4 = d[3] - d[4];

    let tmp10 = tmp0 + tmp3;
    let tmp13 = tmp0 - tmp3;
    let tmp11 = tmp1 + tmp2;
    let tmp12 = tmp1 - tmp2;
    d[0] = tmp10 + tmp11;
    d[4] = tmp10 - tmp11;
    let z1 = (tmp12 + tmp13) * 0.707106781;
    d[2] = tmp13 + z1;
    d[6] = tmp13 - z1;

    let tmp10 = tmp4 + tmp5;
    let tmp11 = tmp5 + tmp6;
    let tmp12 = tmp6 + tmp7;
    let z5 = (tmp10 - tmp12) * 0.382683433;
    let z2 = 0.541196100 * tmp10 + z5;
    let z4 = 1.306562965 * tmp12 + z5;
    let z3 = tmp11 * 0.707106781;
    let z11 = tmp7 + z3;
    let z13 = tmp7 - z3;
    d[5] = z13 + z2;
    d[3] = z13 - z2;
    d[1] = z11 + z4;
    d[7] = z11 - z4;
}

/// Forward DCT + quantization of an 8x8 block of samples (level shifted inside).
pub fn fdct_quantize(samples: &[u8; 64], div: &[f32; 64], out: &mut [i16]) {
    let mut ws = [0f32; 64];
    for r in 0..8 {
        let mut row = [0f32; 8];
        for c in 0..8 {
            row[c] = samples[r * 8 + c] as f32 - 128.0;
        }
        fdct_1d(&mut row);
        ws[r * 8..r * 8 + 8].copy_from_slice(&row);
    }
    for c in 0..8 {
        let mut col = [0f32; 8];
        for r in 0..8 {
            col[r] = ws[r * 8 + c];
        }
        fdct_1d(&mut col);
        for r in 0..8 {
            ws[r * 8 + c] = col[r];
        }
    }
    for i in 0..64 {
        let v = ws[i] * div[i];
        out[i] = v.round().clamp(-32767.0, 32767.0) as i16;
    }
}

// ---------------------------------------------------------------------------
// Huffman table construction
// ---------------------------------------------------------------------------

#[derive(Clone)]
pub struct HuffTable {
    pub counts: [u8; 16],
    pub symbols: Vec<u8>,
    code: [u32; 256],
    size: [u8; 256],
}

impl HuffTable {
    /// Builds an optimal length-limited Huffman table from symbol frequencies.
    pub fn from_freq(freq_in: &[u32; 256]) -> HuffTable {
        let mut freq = [0i64; 257];
        for i in 0..256 {
            freq[i] = freq_in[i] as i64;
        }
        freq[256] = 1; // reserved codepoint
        let mut codesize = [0i32; 257];
        let mut others = [-1i32; 257];
        loop {
            // find two smallest nonzero frequencies
            let mut c1: i32 = -1;
            let mut v = i64::MAX;
            for i in 0..257 {
                if freq[i] != 0 && freq[i] <= v {
                    v = freq[i];
                    c1 = i as i32;
                }
            }
            let mut c2: i32 = -1;
            v = i64::MAX;
            for i in 0..257 {
                if freq[i] != 0 && freq[i] <= v && i as i32 != c1 {
                    v = freq[i];
                    c2 = i as i32;
                }
            }
            if c2 < 0 {
                break;
            }
            let (c1u, c2u) = (c1 as usize, c2 as usize);
            freq[c1u] += freq[c2u];
            freq[c2u] = 0;
            codesize[c1u] += 1;
            let mut i = c1u;
            while others[i] >= 0 {
                i = others[i] as usize;
                codesize[i] += 1;
            }
            others[i] = c2;
            codesize[c2u] += 1;
            let mut i = c2u;
            while others[i] >= 0 {
                i = others[i] as usize;
                codesize[i] += 1;
            }
        }
        let mut bits = [0i32; 33];
        for i in 0..257 {
            if codesize[i] > 0 {
                bits[codesize[i] as usize] += 1;
            }
        }
        // limit to 16 bits
        let mut i = 32usize;
        while i > 16 {
            while bits[i] > 0 {
                let mut j = i - 2;
                while bits[j] == 0 {
                    j -= 1;
                }
                bits[i] -= 2;
                bits[i - 1] += 1;
                bits[j + 1] += 2;
                bits[j] -= 1;
            }
            i -= 1;
        }
        while bits[i] == 0 {
            i -= 1;
        }
        bits[i] -= 1; // remove reserved codepoint
        let mut counts = [0u8; 16];
        for l in 1..=16 {
            counts[l - 1] = bits[l] as u8;
        }
        let mut symbols = Vec::new();
        for len in 1..=32 {
            for s in 0..256 {
                if codesize[s] == len {
                    symbols.push(s as u8);
                }
            }
        }
        let mut t = HuffTable {
            counts,
            symbols,
            code: [0; 256],
            size: [0; 256],
        };
        t.derive_codes();
        t
    }

    fn derive_codes(&mut self) {
        let mut code = 0u32;
        let mut k = 0usize;
        for l in 1..=16u32 {
            for _ in 0..self.counts[l as usize - 1] {
                let s = self.symbols[k] as usize;
                self.code[s] = code;
                self.size[s] = l as u8;
                code += 1;
                k += 1;
            }
            code <<= 1;
        }
    }
}

// ---------------------------------------------------------------------------
// Bit writer
// ---------------------------------------------------------------------------

struct BitWriter {
    out: Vec<u8>,
    acc: u64,
    nbits: u32,
}

impl BitWriter {
    fn new() -> BitWriter {
        BitWriter {
            out: Vec::new(),
            acc: 0,
            nbits: 0,
        }
    }

    #[inline]
    fn put(&mut self, code: u32, size: u32) {
        if size == 0 {
            return;
        }
        self.acc = (self.acc << size) | (code as u64 & ((1u64 << size) - 1));
        self.nbits += size;
        while self.nbits >= 8 {
            let b = (self.acc >> (self.nbits - 8)) as u8;
            self.out.push(b);
            if b == 0xFF {
                self.out.push(0);
            }
            self.nbits -= 8;
        }
    }

    fn flush(&mut self) {
        if self.nbits > 0 {
            let pad = 8 - self.nbits;
            self.put((1u32 << pad) - 1, pad);
        }
    }
}

/// Target of the entropy coder: either statistics gathering or output.
enum Sink<'a> {
    Count {
        dc: &'a mut [[u32; 256]; 4],
        ac: &'a mut [[u32; 256]; 4],
    },
    Write {
        dc: &'a [Option<HuffTable>; 4],
        ac: &'a [Option<HuffTable>; 4],
        w: &'a mut BitWriter,
    },
}

impl<'a> Sink<'a> {
    #[inline]
    fn dc_symbol(&mut self, tbl: usize, sym: u8) {
        match self {
            Sink::Count { dc, .. } => dc[tbl][sym as usize] += 1,
            Sink::Write { dc, w, .. } => {
                let t = dc[tbl].as_ref().expect("dc table");
                w.put(t.code[sym as usize], t.size[sym as usize] as u32);
            }
        }
    }

    #[inline]
    fn ac_symbol(&mut self, tbl: usize, sym: u8) {
        match self {
            Sink::Count { ac, .. } => ac[tbl][sym as usize] += 1,
            Sink::Write { ac, w, .. } => {
                let t = ac[tbl].as_ref().expect("ac table");
                w.put(t.code[sym as usize], t.size[sym as usize] as u32);
            }
        }
    }

    #[inline]
    fn bits(&mut self, value: u32, size: u32) {
        if let Sink::Write { w, .. } = self {
            w.put(value, size);
        }
    }
}

#[inline]
fn nbits_of(v: i32) -> u32 {
    32 - (v.unsigned_abs()).leading_zeros()
}

struct ScanSpec {
    comps: Vec<usize>,
    ss: usize,
    se: usize,
    al: u32,
}

/// Encoder state for one scan.
struct ScanState {
    dc_pred: [i32; 4],
    eobrun: u32,
    /// Buffered EOBRUN extra bits for progressive AC scans.
    be_buffer: Vec<(u32, u32)>,
}

fn emit_eobrun(sink: &mut Sink, tbl: usize, st: &mut ScanState) {
    if st.eobrun > 0 {
        let mut temp = st.eobrun;
        let mut nbits = 0u32;
        temp >>= 1;
        while temp > 0 {
            nbits += 1;
            temp >>= 1;
        }
        sink.ac_symbol(tbl, (nbits << 4) as u8);
        if nbits > 0 {
            sink.bits(st.eobrun, nbits);
        }
        st.eobrun = 0;
        st.be_buffer.clear();
    }
}

fn encode_block(
    sink: &mut Sink,
    coeffs: &[i16],
    dc_tbl: usize,
    ac_tbl: usize,
    scan: &ScanSpec,
    progressive: bool,
    comp_idx_in_scan: usize,
    st: &mut ScanState,
) {
    if scan.ss == 0 {
        // DC coefficient
        let mut dc = coeffs[0] as i32;
        if progressive {
            dc >>= scan.al;
        }
        let diff = dc - st.dc_pred[comp_idx_in_scan];
        st.dc_pred[comp_idx_in_scan] = dc;
        let nb = nbits_of(diff);
        sink.dc_symbol(dc_tbl, nb as u8);
        if nb > 0 {
            let v = if diff < 0 { diff - 1 } else { diff };
            sink.bits(v as u32, nb);
        }
        if scan.se == 0 {
            return;
        }
    }
    let start = scan.ss.max(1);
    if !progressive {
        let mut run = 0u32;
        for k in start..=scan.se {
            let v = coeffs[ZIGZAG[k]] as i32;
            if v == 0 {
                run += 1;
                continue;
            }
            while run > 15 {
                sink.ac_symbol(ac_tbl, 0xF0);
                run -= 16;
            }
            let nb = nbits_of(v);
            sink.ac_symbol(ac_tbl, ((run << 4) | nb) as u8);
            let bits = if v < 0 { v - 1 } else { v };
            sink.bits(bits as u32, nb);
            run = 0;
        }
        if run > 0 {
            sink.ac_symbol(ac_tbl, 0x00);
        }
        return;
    }
    // Progressive AC first scan
    let mut run = 0u32;
    let mut emitted_any = false;
    for k in start..=scan.se {
        let mut v = coeffs[ZIGZAG[k]] as i32;
        if v == 0 {
            run += 1;
            continue;
        }
        let bits_val: i32;
        if v < 0 {
            v = -v;
            v >>= scan.al;
            bits_val = !v;
        } else {
            v >>= scan.al;
            bits_val = v;
        }
        if v == 0 {
            run += 1;
            continue;
        }
        emit_eobrun(sink, ac_tbl, st);
        while run > 15 {
            sink.ac_symbol(ac_tbl, 0xF0);
            run -= 16;
        }
        let nb = nbits_of(v);
        sink.ac_symbol(ac_tbl, ((run << 4) | nb) as u8);
        sink.bits(bits_val as u32, nb);
        run = 0;
        emitted_any = true;
    }
    let _ = emitted_any;
    if run > 0 {
        st.eobrun += 1;
        if st.eobrun == 0x7FFF {
            emit_eobrun(sink, ac_tbl, st);
        }
    }
}

pub struct EncodeOptions {
    pub progressive: bool,
    pub jfif_version: (u8, u8),
    /// Extra marker segments written right after the JFIF header.
    pub markers: Vec<Marker>,
}

fn write_segment(out: &mut Vec<u8>, marker: u8, payload: &[u8]) {
    out.push(0xFF);
    out.push(marker);
    let len = payload.len() + 2;
    out.push((len >> 8) as u8);
    out.push(len as u8);
    out.extend_from_slice(payload);
}

fn write_dht(out: &mut Vec<u8>, tables: &[(u8, u8, &HuffTable)]) {
    let mut payload = Vec::new();
    for (class, id, t) in tables {
        payload.push((class << 4) | id);
        payload.extend_from_slice(&t.counts);
        payload.extend_from_slice(&t.symbols);
    }
    write_segment(out, 0xC4, &payload);
}

fn build_scan_script(ncomp: usize, progressive: bool) -> Vec<ScanSpec> {
    let all: Vec<usize> = (0..ncomp).collect();
    if !progressive {
        return vec![ScanSpec {
            comps: all,
            ss: 0,
            se: 63,
            al: 0,
        }];
    }
    let mut scans = vec![ScanSpec {
        comps: all,
        ss: 0,
        se: 0,
        al: 0,
    }];
    if ncomp == 1 {
        scans.push(ScanSpec {
            comps: vec![0],
            ss: 1,
            se: 63,
            al: 0,
        });
    } else {
        scans.push(ScanSpec {
            comps: vec![0],
            ss: 1,
            se: 8,
            al: 0,
        });
        scans.push(ScanSpec {
            comps: vec![0],
            ss: 9,
            se: 63,
            al: 0,
        });
        for c in 1..ncomp {
            scans.push(ScanSpec {
                comps: vec![c],
                ss: 1,
                se: 63,
                al: 0,
            });
        }
    }
    scans
}

fn table_id(comp: usize) -> usize {
    if comp == 0 {
        0
    } else {
        1
    }
}

/// Runs the entropy coder over a scan for either statistics or output.
fn run_scan(
    sink: &mut Sink,
    comps: &[Component],
    scan: &ScanSpec,
    progressive: bool,
    mcux: usize,
    mcuy: usize,
) {
    let mut st = ScanState {
        dc_pred: [0; 4],
        eobrun: 0,
        be_buffer: Vec::new(),
    };
    if scan.comps.len() == 1 {
        let ci = scan.comps[0];
        let c = &comps[ci];
        let tbl = table_id(ci);
        for by in 0..c.used_h {
            for bx in 0..c.used_w {
                let off = (by * c.blocks_w + bx) * 64;
                encode_block(sink, &c.coeffs[off..off + 64], tbl, tbl, scan, progressive, 0, &mut st);
            }
        }
    } else {
        for my in 0..mcuy {
            for mx in 0..mcux {
                for (si, &ci) in scan.comps.iter().enumerate() {
                    let c = &comps[ci];
                    let tbl = table_id(ci);
                    for yy in 0..c.v {
                        for xx in 0..c.h {
                            let bx = mx * c.h + xx;
                            let by = my * c.v + yy;
                            let off = (by * c.blocks_w + bx) * 64;
                            encode_block(sink, &c.coeffs[off..off + 64], tbl, tbl, scan, progressive, si, &mut st);
                        }
                    }
                }
            }
        }
    }
    if progressive && scan.ss > 0 {
        emit_eobrun(sink, table_id(scan.comps[0]), &mut st);
    }
}

/// Encodes quantized coefficient blocks into a complete JPEG file.
pub fn encode_from_components(
    width: u32,
    height: u32,
    comps: &[Component],
    qt: &[[u16; 64]],
    opts: &EncodeOptions,
) -> Vec<u8> {
    let ncomp = comps.len();
    let hmax = comps.iter().map(|c| c.h).max().unwrap_or(1);
    let vmax = comps.iter().map(|c| c.v).max().unwrap_or(1);
    let mcux = (width as usize + 8 * hmax - 1) / (8 * hmax);
    let mcuy = (height as usize + 8 * vmax - 1) / (8 * vmax);
    let progressive = opts.progressive;

    let mut out = Vec::new();
    out.extend_from_slice(&[0xFF, 0xD8]);
    // JFIF
    let mut app0 = Vec::new();
    app0.extend_from_slice(b"JFIF\0");
    app0.push(opts.jfif_version.0);
    app0.push(opts.jfif_version.1);
    app0.push(0);
    app0.extend_from_slice(&[0, 1, 0, 1, 0, 0]);
    write_segment(&mut out, 0xE0, &app0);
    for m in &opts.markers {
        write_segment(&mut out, m.marker, &m.data);
    }
    // DQT: only tables referenced by components
    let mut used_tables: Vec<usize> = comps.iter().map(|c| c.tq).collect();
    used_tables.sort_unstable();
    used_tables.dedup();
    let mut dqt = Vec::new();
    for &tq in &used_tables {
        let table = &qt[tq.min(qt.len() - 1)];
        let precision = if table.iter().any(|&v| v > 255) { 1u8 } else { 0u8 };
        dqt.push((precision << 4) | tq as u8);
        for k in 0..64 {
            let v = table[ZIGZAG[k]];
            if precision == 1 {
                dqt.push((v >> 8) as u8);
            }
            dqt.push(v as u8);
        }
    }
    write_segment(&mut out, 0xDB, &dqt);
    // SOF
    let mut sof = Vec::new();
    sof.push(8);
    sof.extend_from_slice(&(height as u16).to_be_bytes());
    sof.extend_from_slice(&(width as u16).to_be_bytes());
    sof.push(ncomp as u8);
    for c in comps {
        sof.push(c.id);
        sof.push(((c.h as u8) << 4) | c.v as u8);
        sof.push(c.tq as u8);
    }
    write_segment(&mut out, if progressive { 0xC2 } else { 0xC0 }, &sof);

    let scans = build_scan_script(ncomp, progressive);
    if !progressive {
        // gather stats for the single scan, write one DHT with all tables
        let mut dc_freq = [[0u32; 256]; 4];
        let mut ac_freq = [[0u32; 256]; 4];
        {
            let mut sink = Sink::Count {
                dc: &mut dc_freq,
                ac: &mut ac_freq,
            };
            run_scan(&mut sink, comps, &scans[0], false, mcux, mcuy);
        }
        let mut dc_tables: [Option<HuffTable>; 4] = [None, None, None, None];
        let mut ac_tables: [Option<HuffTable>; 4] = [None, None, None, None];
        let ntables = if ncomp == 1 { 1 } else { 2 };
        let mut dht_list: Vec<(u8, u8, HuffTable)> = Vec::new();
        for t in 0..ntables {
            let dct = HuffTable::from_freq(&dc_freq[t]);
            let act = HuffTable::from_freq(&ac_freq[t]);
            dht_list.push((0, t as u8, dct.clone()));
            dht_list.push((1, t as u8, act.clone()));
            dc_tables[t] = Some(dct);
            ac_tables[t] = Some(act);
        }
        let refs: Vec<(u8, u8, &HuffTable)> = dht_list.iter().map(|(c, i, t)| (*c, *i, t)).collect();
        write_dht(&mut out, &refs);
        write_sos(&mut out, comps, &scans[0], 0);
        let mut w = BitWriter::new();
        {
            let mut sink = Sink::Write {
                dc: &dc_tables,
                ac: &ac_tables,
                w: &mut w,
            };
            run_scan(&mut sink, comps, &scans[0], false, mcux, mcuy);
        }
        w.flush();
        out.extend_from_slice(&w.out);
    } else {
        for scan in &scans {
            let mut dc_freq = [[0u32; 256]; 4];
            let mut ac_freq = [[0u32; 256]; 4];
            {
                let mut sink = Sink::Count {
                    dc: &mut dc_freq,
                    ac: &mut ac_freq,
                };
                run_scan(&mut sink, comps, scan, true, mcux, mcuy);
            }
            let mut dc_tables: [Option<HuffTable>; 4] = [None, None, None, None];
            let mut ac_tables: [Option<HuffTable>; 4] = [None, None, None, None];
            let mut dht_list: Vec<(u8, u8, HuffTable)> = Vec::new();
            let mut tbl_ids: Vec<usize> = scan.comps.iter().map(|&c| table_id(c)).collect();
            tbl_ids.sort_unstable();
            tbl_ids.dedup();
            for &t in &tbl_ids {
                if scan.ss == 0 {
                    let dct = HuffTable::from_freq(&dc_freq[t]);
                    dht_list.push((0, t as u8, dct.clone()));
                    dc_tables[t] = Some(dct);
                }
                if scan.se > 0 {
                    let act = HuffTable::from_freq(&ac_freq[t]);
                    dht_list.push((1, t as u8, act.clone()));
                    ac_tables[t] = Some(act);
                }
            }
            let refs: Vec<(u8, u8, &HuffTable)> = dht_list.iter().map(|(c, i, t)| (*c, *i, t)).collect();
            write_dht(&mut out, &refs);
            write_sos(&mut out, comps, scan, 0);
            let mut w = BitWriter::new();
            {
                let mut sink = Sink::Write {
                    dc: &dc_tables,
                    ac: &ac_tables,
                    w: &mut w,
                };
                run_scan(&mut sink, comps, scan, true, mcux, mcuy);
            }
            w.flush();
            out.extend_from_slice(&w.out);
        }
    }
    out.extend_from_slice(&[0xFF, 0xD9]);
    out
}

fn write_sos(out: &mut Vec<u8>, comps: &[Component], scan: &ScanSpec, ah: u32) {
    let mut sos = Vec::new();
    sos.push(scan.comps.len() as u8);
    for &ci in &scan.comps {
        sos.push(comps[ci].id);
        let t = table_id(ci) as u8;
        sos.push((t << 4) | t);
    }
    sos.push(scan.ss as u8);
    sos.push(scan.se as u8);
    sos.push(((ah as u8) << 4) | scan.al as u8);
    write_segment(out, 0xDA, &sos);
}

// ---------------------------------------------------------------------------
// Encoding from pixels
// ---------------------------------------------------------------------------

#[inline]
fn rgb_to_ycc(r: i32, g: i32, b: i32) -> (u8, u8, u8) {
    // Fixed point with 16 fractional bits
    let y = (19595 * r + 38470 * g + 7471 * b + 32768) >> 16;
    let cb = ((-11059 * r - 21709 * g + 32768 * b + 32768) >> 16) + 128;
    let cr = ((32768 * r - 27439 * g - 5329 * b + 32768) >> 16) + 128;
    (
        y.clamp(0, 255) as u8,
        cb.clamp(0, 255) as u8,
        cr.clamp(0, 255) as u8,
    )
}

/// Builds a padded sample plane for a component by downsampling the full
/// resolution plane by (hs, vs) with box averaging.
fn downsample(plane: &[u8], w: usize, h: usize, hs: usize, vs: usize, out_w: usize, out_h: usize) -> Vec<u8> {
    let mut out = vec![0u8; out_w * out_h];
    let cw = (w + hs - 1) / hs;
    let ch = (h + vs - 1) / vs;
    for y in 0..out_h {
        for x in 0..out_w {
            let sx = x.min(cw - 1);
            let sy = y.min(ch - 1);
            let mut sum = 0u32;
            let mut n = 0u32;
            for dy in 0..vs {
                let yy = (sy * vs + dy).min(h - 1);
                for dx in 0..hs {
                    let xx = (sx * hs + dx).min(w - 1);
                    sum += plane[yy * w + xx] as u32;
                    n += 1;
                }
            }
            out[y * out_w + x] = ((sum + n / 2) / n) as u8;
        }
    }
    out
}

fn plane_to_blocks(plane: &[u8], pw: usize, ph: usize, div: &[f32; 64]) -> Vec<i16> {
    let bw = pw / 8;
    let bh = ph / 8;
    let mut coeffs = vec![0i16; bw * bh * 64];
    let mut block = [0u8; 64];
    for by in 0..bh {
        for bx in 0..bw {
            for y in 0..8 {
                let row = (by * 8 + y) * pw + bx * 8;
                block[y * 8..y * 8 + 8].copy_from_slice(&plane[row..row + 8]);
            }
            let off = (by * bw + bx) * 64;
            fdct_quantize(&block, div, &mut coeffs[off..off + 64]);
        }
    }
    coeffs
}

/// Encodes an RGBA image as JPEG. `chroma` is the (h, v) sampling of the
/// luma component; `None` encodes a single grayscale component.
pub fn encode_image(
    img: &Image,
    quality: u32,
    chroma: Option<(usize, usize)>,
    tables: QuantTables,
    opts: &EncodeOptions,
) -> Vec<u8> {
    let w = img.width as usize;
    let h = img.height as usize;
    let qt = quant_tables(tables, quality);
    let mut comps: Vec<Component> = Vec::new();
    match chroma {
        None => {
            let pw = (w + 7) / 8 * 8;
            let ph = (h + 7) / 8 * 8;
            let mut plane = vec![0u8; pw * ph];
            for y in 0..ph {
                let sy = y.min(h - 1);
                for x in 0..pw {
                    let sx = x.min(w - 1);
                    plane[y * pw + x] = img.data[(sy * w + sx) * 4];
                }
            }
            let div = divisors(&qt[0]);
            let coeffs = plane_to_blocks(&plane, pw, ph, &div);
            comps.push(Component {
                id: 1,
                h: 1,
                v: 1,
                tq: 0,
                blocks_w: pw / 8,
                blocks_h: ph / 8,
                used_w: pw / 8,
                used_h: ph / 8,
                coeffs,
            });
        }
        Some((hs, vs)) => {
            let hs = hs.clamp(1, 4);
            let vs = vs.clamp(1, 4);
            let mcux = (w + 8 * hs - 1) / (8 * hs);
            let mcuy = (h + 8 * vs - 1) / (8 * vs);
            let mut yp = vec![0u8; w * h];
            let mut cbp = vec![0u8; w * h];
            let mut crp = vec![0u8; w * h];
            for i in 0..w * h {
                let p = &img.data[i * 4..i * 4 + 4];
                let (y, cb, cr) = rgb_to_ycc(p[0] as i32, p[1] as i32, p[2] as i32);
                yp[i] = y;
                cbp[i] = cb;
                crp[i] = cr;
            }
            // luma plane padded
            let lpw = mcux * 8 * hs;
            let lph = mcuy * 8 * vs;
            let luma = downsample(&yp, w, h, 1, 1, lpw, lph);
            let div0 = divisors(&qt[0]);
            let div1 = divisors(&qt[1]);
            let lcoeffs = plane_to_blocks(&luma, lpw, lph, &div0);
            comps.push(Component {
                id: 1,
                h: hs,
                v: vs,
                tq: 0,
                blocks_w: lpw / 8,
                blocks_h: lph / 8,
                used_w: (w + 7) / 8,
                used_h: (h + 7) / 8,
                coeffs: lcoeffs,
            });
            let cpw = mcux * 8;
            let cph = mcuy * 8;
            let cw = (w + hs - 1) / hs;
            let ch = (h + vs - 1) / vs;
            for (id, plane) in [(2u8, &cbp), (3u8, &crp)] {
                let ds = downsample(plane, w, h, hs, vs, cpw, cph);
                let coeffs = plane_to_blocks(&ds, cpw, cph, &div1);
                comps.push(Component {
                    id,
                    h: 1,
                    v: 1,
                    tq: 1,
                    blocks_w: cpw / 8,
                    blocks_h: cph / 8,
                    used_w: (cw + 7) / 8,
                    used_h: (ch + 7) / 8,
                    coeffs,
                });
            }
        }
    }
    encode_from_components(img.width, img.height, &comps, &qt, opts)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fdct_matches_reference() {
        let mut samples = [0u8; 64];
        for (i, s) in samples.iter_mut().enumerate() {
            *s = ((i * 37 + 11) % 256) as u8;
        }
        let q = [1u16; 64];
        let div = divisors(&q);
        let mut out = [0i16; 64];
        fdct_quantize(&samples, &div, &mut out);
        for v in 0..8 {
            for u in 0..8 {
                let mut s = 0f64;
                for y in 0..8 {
                    for x in 0..8 {
                        s += (samples[y * 8 + x] as f64 - 128.0)
                            * ((2.0 * x as f64 + 1.0) * u as f64 * std::f64::consts::PI / 16.0).cos()
                            * ((2.0 * y as f64 + 1.0) * v as f64 * std::f64::consts::PI / 16.0).cos();
                    }
                }
                let cu = if u == 0 { 1.0 / 2f64.sqrt() } else { 1.0 };
                let cv = if v == 0 { 1.0 / 2f64.sqrt() } else { 1.0 };
                let val = (s * cu * cv / 4.0).round() as i32;
                assert!((val - out[v * 8 + u] as i32).abs() <= 1, "mismatch at {},{}: {} vs {}", u, v, val, out[v * 8 + u]);
            }
        }
    }
}
