//! GIF flavoured LZW compression and decompression.

pub fn decode(data: &[u8], min_code_size: u8, expected: usize) -> Result<Vec<u8>, String> {
    let min_code_size = min_code_size.clamp(2, 11) as u32;
    let clear = 1u32 << min_code_size;
    let end = clear + 1;
    let mut code_size = min_code_size + 1;
    let mut next_code = end + 1;
    // dictionary: prefix code and suffix byte, plus length
    let mut prefix = vec![0u16; 4096];
    let mut suffix = vec![0u8; 4096];
    let mut length = vec![0u16; 4096];
    for i in 0..clear as usize {
        suffix[i] = i as u8;
        length[i] = 1;
    }
    let mut out = Vec::with_capacity(expected);
    let mut bitbuf = 0u32;
    let mut nbits = 0u32;
    let mut pos = 0usize;
    let mut prev: Option<u32> = None;
    let mut stack = Vec::with_capacity(4096);
    loop {
        while nbits < code_size {
            if pos >= data.len() {
                // Truncated stream: tolerate if we have enough pixels.
                if out.len() >= expected {
                    return Ok(out);
                }
                return Err("unexpected end of LZW data".to_string());
            }
            bitbuf |= (data[pos] as u32) << nbits;
            nbits += 8;
            pos += 1;
        }
        let code = bitbuf & ((1 << code_size) - 1);
        bitbuf >>= code_size;
        nbits -= code_size;
        if code == clear {
            code_size = min_code_size + 1;
            next_code = end + 1;
            prev = None;
            continue;
        }
        if code == end {
            break;
        }
        let first_byte: u8;
        if code < next_code && (code < clear || prev.is_some() || code < clear) {
            // output string for code
            if code >= clear && prev.is_none() {
                return Err("invalid LZW code".to_string());
            }
            let mut c = code as usize;
            stack.clear();
            loop {
                stack.push(suffix[c]);
                if (c as u32) < clear {
                    break;
                }
                c = prefix[c] as usize;
            }
            first_byte = *stack.last().unwrap();
            for &b in stack.iter().rev() {
                out.push(b);
            }
        } else if code == next_code && prev.is_some() {
            let p = prev.unwrap() as usize;
            let mut c = p;
            stack.clear();
            loop {
                stack.push(suffix[c]);
                if (c as u32) < clear {
                    break;
                }
                c = prefix[c] as usize;
            }
            first_byte = *stack.last().unwrap();
            for &b in stack.iter().rev() {
                out.push(b);
            }
            out.push(first_byte);
        } else {
            return Err("invalid LZW code".to_string());
        }
        if let Some(p) = prev {
            if next_code < 4096 {
                prefix[next_code as usize] = p as u16;
                suffix[next_code as usize] = first_byte;
                length[next_code as usize] = length[p as usize] + 1;
                next_code += 1;
                if next_code == (1 << code_size) && code_size < 12 {
                    code_size += 1;
                }
            }
        }
        prev = Some(code);
        if out.len() >= expected && expected > 0 {
            // Enough pixels decoded; ignore the rest.
            break;
        }
    }
    Ok(out)
}

/// Lossy matching parameters for the encoder.
pub struct Lossy<'a> {
    /// Palette used to measure color distances.
    pub palette: &'a [[u8; 3]],
    /// Maximum squared distance accepted for one pixel substitution.
    pub max_pixel_err: u32,
    /// Maximum accumulated squared error along a single LZW string.
    pub max_total_err: u32,
    /// Index that must never be substituted (transparency).
    pub transparent: Option<u8>,
}

struct BitPacker {
    out: Vec<u8>,
    acc: u32,
    nbits: u32,
}

impl BitPacker {
    fn put(&mut self, code: u32, size: u32) {
        self.acc |= code << self.nbits;
        self.nbits += size;
        while self.nbits >= 8 {
            self.out.push(self.acc as u8);
            self.acc >>= 8;
            self.nbits -= 8;
        }
    }
    fn flush(&mut self) {
        if self.nbits > 0 {
            self.out.push(self.acc as u8);
            self.acc = 0;
            self.nbits = 0;
        }
    }
}

fn color_dist(a: [u8; 3], b: [u8; 3]) -> u32 {
    let dr = a[0] as i32 - b[0] as i32;
    let dg = a[1] as i32 - b[1] as i32;
    let db = a[2] as i32 - b[2] as i32;
    (dr * dr + dg * dg + db * db) as u32
}

/// Encodes indices with GIF LZW. When `lossy` is given, pixels may be
