        out.push(min_code_size);
        write_sub_blocks(&mut out, &compressed);
    }
    for ext in &gif.trailing_extensions {
        write_extension(&mut out, ext);
    }
    out.push(0x3B);
    out
}

/// Encodes an RGBA image as a single frame GIF.
pub fn encode_image(img: &Image, quality: u32) -> Vec<u8> {
    let has_alpha = img.data.chunks_exact(4).any(|p| p[3] < 128);
    let max_colors = if has_alpha { 255 } else { 256 };
    // Quantize ignoring alpha (alpha handled as a transparent index)
    let mut opaque = img.clone();
    for p in opaque.data.chunks_exact_mut(4) {
        p[3] = 255;
    }
    let q = quant::quantize(&opaque, quality, max_colors);
    let mut palette: Vec<[u8; 3]> = q.palette.iter().map(|c| [c[0], c[1], c[2]]).collect();
    let mut indices = q.indices;
    let mut transparent = None;
    if has_alpha {
        let tidx = palette.len() as u8;
        palette.push([0, 0, 0]);
        for (i, p) in img.data.chunks_exact(4).enumerate() {
            if p[3] < 128 {
                indices[i] = tidx;
            }
        }
        transparent = Some(tidx);
    }
    let gif = Gif {
        version: *b"89a",
        width: img.width as u16,
        height: img.height as u16,
        global_palette: Some(palette),
        background: 0,
        aspect: 0,
        color_resolution: 7,
