            width: img.width as u16,
            height: img.height as u16,
            local_palette: None,
            interlaced: false,
            indices,
            transparent,
            delay: 0,
            disposal: 0,
            user_input: false,
            has_gce: true,
            extensions: Vec::new(),
        }],
        trailing_extensions: Vec::new(),
    };
