//! GIF parsing, re-encoding and conversion.

use crate::codecs::lzw;
use crate::codecs::quant;
use crate::image::Image;

#[derive(Debug, Clone)]
pub struct Frame {
    pub left: u16,
    pub top: u16,
    pub width: u16,
    pub height: u16,
    pub local_palette: Option<Vec<[u8; 3]>>,
    pub interlaced: bool,
    /// Decoded indices (de-interlaced), width * height.
    pub indices: Vec<u8>,
    pub transparent: Option<u8>,
    pub delay: u16,
    pub disposal: u8,
    pub user_input: bool,
    pub has_gce: bool,
    /// Extensions (other than the GCE) preceding this frame, raw bodies.
    pub extensions: Vec<Extension>,
}

#[derive(Debug, Clone)]
pub struct Extension {
    pub label: u8,
    /// Concatenated sub-block payload.
    pub data: Vec<u8>,
}

#[derive(Debug, Clone)]
pub struct Gif {
    pub version: [u8; 3],
    pub width: u16,
    pub height: u16,
    pub global_palette: Option<Vec<[u8; 3]>>,
    pub background: u8,
    pub aspect: u8,
    pub color_resolution: u8,
    pub frames: Vec<Frame>,
    /// Extensions found after the last frame.
    pub trailing_extensions: Vec<Extension>,
}

fn read_sub_blocks(data: &[u8], mut pos: usize) -> Result<(Vec<u8>, usize), String> {
    let mut out = Vec::new();
    loop {
        let len = *data.get(pos).ok_or_else(|| "unexpected end of file".to_string())? as usize;
        pos += 1;
        if len == 0 {
            break;
        }
        let block = data
            .get(pos..pos + len)
            .ok_or_else(|| "unexpected end of file".to_string())?;
        out.extend_from_slice(block);
        pos += len;
    }
    Ok((out, pos))
}

fn read_palette(data: &[u8], pos: usize, n: usize) -> Result<Vec<[u8; 3]>, String> {
    let bytes = data
        .get(pos..pos + n * 3)
        .ok_or_else(|| "unexpected end of file".to_string())?;
    Ok(bytes.chunks_exact(3).map(|c| [c[0], c[1], c[2]]).collect())
}

fn deinterlace(indices: &[u8], w: usize, h: usize) -> Vec<u8> {
    let mut out = vec![0u8; w * h];
    let mut src_row = 0usize;
    for &(start, step) in &[(0usize, 8usize), (4, 8), (2, 4), (1, 2)] {
        let mut y = start;
        while y < h {
            if src_row * w + w <= indices.len() {
                out[y * w..(y + 1) * w].copy_from_slice(&indices[src_row * w..(src_row + 1) * w]);
            }
            src_row += 1;
            y += step;
        }
    }
    out
}

pub fn decode(data: &[u8]) -> Result<Gif, String> {
    if data.len() < 13 || &data[0..3] != b"GIF" {
        return Err("Found no usable frames to encode".to_string());
    }
    let version = [data[3], data[4], data[5]];
    let width = u16::from_le_bytes([data[6], data[7]]);
    let height = u16::from_le_bytes([data[8], data[9]]);
    let flags = data[10];
    let background = data[11];
    let aspect = data[12];
    let mut pos = 13usize;
    let mut global_palette = None;
    if flags & 0x80 != 0 {
        let n = 2usize << (flags & 7);
        global_palette = Some(read_palette(data, pos, n)?);
        pos += n * 3;
    }
    let mut frames = Vec::new();
    let mut pending_ext: Vec<Extension> = Vec::new();
    let mut gce: Option<(u8, u16, u8)> = None; // (flags, delay, transparent index)
    loop {
        let b = match data.get(pos) {
            Some(&b) => b,
            None => break, // missing trailer: tolerate
        };
        pos += 1;
        match b {
            0x3B => break,
            0x21 => {
                let label = *data.get(pos).ok_or_else(|| "unexpected end of file".to_string())?;
                pos += 1;
                let (body, np) = read_sub_blocks(data, pos)?;
                pos = np;
                if label == 0xF9 {
                    if body.len() >= 4 {
                        gce = Some((body[0], u16::from_le_bytes([body[1], body[2]]), body[3]));
                    }
                } else {
                    pending_ext.push(Extension { label, data: body });
                }
            }
            0x2C => {
                if pos + 9 > data.len() {
                    return Err("unexpected end of file".to_string());
                }
                let left = u16::from_le_bytes([data[pos], data[pos + 1]]);
                let top = u16::from_le_bytes([data[pos + 2], data[pos + 3]]);
                let fw = u16::from_le_bytes([data[pos + 4], data[pos + 5]]);
                let fh = u16::from_le_bytes([data[pos + 6], data[pos + 7]]);
                let fflags = data[pos + 8];
                pos += 9;
                let mut local_palette = None;
                if fflags & 0x80 != 0 {
                    let n = 2usize << (fflags & 7);
                    local_palette = Some(read_palette(data, pos, n)?);
                    pos += n * 3;
                }
                let min_code_size = *data.get(pos).ok_or_else(|| "unexpected end of file".to_string())?;
                pos += 1;
                let (lzw_data, np) = read_sub_blocks(data, pos)?;
                pos = np;
                let npix = fw as usize * fh as usize;
                if fw == 0 || fh == 0 {
                    return Err("image dimensions are zero".to_string());
                }
                let mut indices = lzw::decode(&lzw_data, min_code_size, npix)?;
                indices.resize(npix, 0);
                let interlaced = fflags & 0x40 != 0;
                if interlaced {
                    indices = deinterlace(&indices, fw as usize, fh as usize);
                }
                let (gflags, delay, tindex) = gce.unwrap_or((0, 0, 0));
                frames.push(Frame {
                    left,
                    top,
                    width: fw,
                    height: fh,
                    local_palette,
                    interlaced,
                    indices,
                    transparent: if gflags & 1 != 0 { Some(tindex) } else { None },
                    delay,
                    disposal: (gflags >> 2) & 7,
                    user_input: gflags & 2 != 0,
                    has_gce: gce.is_some(),
                    extensions: std::mem::take(&mut pending_ext),
                });
                gce = None;
            }
            _ => {
                return Err("unknown block type".to_string());
            }
        }
    }
    if frames.is_empty() {
        return Err("Found no usable frames to encode".to_string());
    }
    Ok(Gif {
        version,
        width,
        height,
        global_palette,
        background,
        aspect,
        color_resolution: (flags >> 4) & 7,
        frames,
        trailing_extensions: pending_ext,
    })
}

/// Renders the first frame onto a transparent canvas.
pub fn first_frame_image(gif: &Gif) -> Result<Image, String> {
    let frame = gif.frames.first().ok_or_else(|| "Found no usable frames to encode".to_string())?;
    let w = gif.width.max(frame.left.saturating_add(frame.width)) as usize;
    let h = gif.height.max(frame.top.saturating_add(frame.height)) as usize;
    let w = if gif.width == 0 { frame.width as usize } else { w };
    let h = if gif.height == 0 { frame.height as usize } else { h };
    if w == 0 || h == 0 {
        return Err("image dimensions are zero".to_string());
    }
    let palette = frame
        .local_palette
        .as_ref()
        .or(gif.global_palette.as_ref())
        .ok_or_else(|| "no color table".to_string())?;
    let mut img = Image::new(w as u32, h as u32);
    for y in 0..frame.height as usize {
        let cy = frame.top as usize + y;
        if cy >= h {
            break;
        }
        for x in 0..frame.width as usize {
            let cx = frame.left as usize + x;
            if cx >= w {
                break;
            }
            let idx = frame.indices[y * frame.width as usize + x];
            if Some(idx) == frame.transparent {
                continue;
            }
            let c = palette.get(idx as usize).copied().unwrap_or([0, 0, 0]);
            let o = (cy * w + cx) * 4;
            img.data[o] = c[0];
            img.data[o + 1] = c[1];
            img.data[o + 2] = c[2];
            img.data[o + 3] = 255;
        }
    }
    Ok(img)
}

fn write_sub_blocks(out: &mut Vec<u8>, data: &[u8]) {
    for chunk in data.chunks(255) {
        out.push(chunk.len() as u8);
        out.extend_from_slice(chunk);
    }
    out.push(0);
}

fn palette_size_code(n: usize) -> (u8, usize) {
    let mut code = 0u8;
    let mut size = 2usize;
    while size < n && code < 7 {
        code += 1;
        size <<= 1;
    }
    (code, size)
}

fn write_palette(out: &mut Vec<u8>, palette: &[[u8; 3]], size: usize) {
    for i in 0..size {
        let c = palette.get(i).copied().unwrap_or([0, 0, 0]);
        out.extend_from_slice(&c);
    }
}

fn write_extension(out: &mut Vec<u8>, ext: &Extension) {
    out.push(0x21);
