//! Minimal TIFF encoder (deflate compressed RGB/RGBA strips).

use crate::codecs::deflate::zlib_compress;
use crate::image::Image;

struct Entry {
    tag: u16,
    kind: u16,
    count: u32,
    /// Raw value bytes (little endian); placed inline when <= 4 bytes.
    value: Vec<u8>,
}

fn shorts(v: &[u16]) -> Vec<u8> {
    v.iter().flat_map(|x| x.to_le_bytes()).collect()
}

fn longs(v: &[u32]) -> Vec<u8> {
    v.iter().flat_map(|x| x.to_le_bytes()).collect()
}

pub fn encode(img: &Image) -> Vec<u8> {
    let w = img.width as usize;
    let h = img.height as usize;
    let alpha = img.has_alpha();
    let spp = if alpha { 4usize } else { 3 };
    let pixels: Vec<u8> = if alpha { img.data.clone() } else { img.to_rgb() };
    let row_bytes = w * spp;
    let rows_per_strip = ((1_000_000 + row_bytes - 1) / row_bytes).max(1).min(h);
    let nstrips = (h + rows_per_strip - 1) / rows_per_strip;

    let mut out = Vec::new();
    out.extend_from_slice(b"II");
    out.extend_from_slice(&42u16.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // IFD offset patched later

    let mut offsets = Vec::with_capacity(nstrips);
    let mut counts = Vec::with_capacity(nstrips);
    for s in 0..nstrips {
        let start = s * rows_per_strip;
        let end = ((s + 1) * rows_per_strip).min(h);
        let raw = &pixels[start * row_bytes..end * row_bytes];
        let comp = zlib_compress(raw, 6);
        offsets.push(out.len() as u32);
        counts.push(comp.len() as u32);
        out.extend_from_slice(&comp);
        if out.len() % 2 == 1 {
            out.push(0);
        }
    }

    let ones = vec![1u16; spp];
    let eights = vec![8u16; spp];
    let mut entries = vec![
        Entry { tag: 256, kind: 4, count: 1, value: longs(&[w as u32]) },
        Entry { tag: 257, kind: 4, count: 1, value: longs(&[h as u32]) },
        Entry { tag: 258, kind: 3, count: spp as u32, value: shorts(&eights) },
        Entry { tag: 259, kind: 3, count: 1, value: shorts(&[8]) },
        Entry { tag: 262, kind: 3, count: 1, value: shorts(&[2]) },
        Entry { tag: 273, kind: 4, count: nstrips as u32, value: longs(&offsets) },
        Entry { tag: 277, kind: 3, count: 1, value: shorts(&[spp as u16]) },
        Entry { tag: 278, kind: 4, count: 1, value: longs(&[rows_per_strip as u32]) },
        Entry { tag: 279, kind: 4, count: nstrips as u32, value: longs(&counts) },
        Entry { tag: 282, kind: 5, count: 1, value: longs(&[1, 1]) },
        Entry { tag: 283, kind: 5, count: 1, value: longs(&[1, 1]) },
        Entry { tag: 296, kind: 3, count: 1, value: shorts(&[1]) },
