//! WebP support through the system libwebp library (loaded at runtime).

use std::ffi::{c_char, c_float, c_int, c_void, CString};
use std::sync::OnceLock;

use crate::image::Image;

type GetInfoFn = unsafe extern "C" fn(*const u8, usize, *mut c_int, *mut c_int) -> c_int;
type DecodeRgbaFn = unsafe extern "C" fn(*const u8, usize, *mut c_int, *mut c_int) -> *mut u8;
type EncodeRgbaFn =
    unsafe extern "C" fn(*const u8, c_int, c_int, c_int, c_float, *mut *mut u8) -> usize;
type EncodeLosslessRgbaFn = unsafe extern "C" fn(*const u8, c_int, c_int, c_int, *mut *mut u8) -> usize;
type FreeFn = unsafe extern "C" fn(*mut c_void);

struct Lib {
    get_info: GetInfoFn,
    decode_rgba: DecodeRgbaFn,
    encode_rgba: EncodeRgbaFn,
    encode_lossless_rgba: EncodeLosslessRgbaFn,
    free: FreeFn,
}

unsafe impl Send for Lib {}
unsafe impl Sync for Lib {}

static LIB: OnceLock<Option<Lib>> = OnceLock::new();

unsafe fn sym<T: Copy>(handle: *mut c_void, name: &str) -> Option<T> {
    let cname = CString::new(name).ok()?;
    let p = libc::dlsym(handle, cname.as_ptr() as *const c_char);
    if p.is_null() {
        return None;
    }
    Some(std::mem::transmute_copy(&p))
}

fn load() -> Option<Lib> {
    let candidates = [
        "libwebp.so.7",
        "libwebp.so",
        "libwebp.so.6",
        "libwebp.dylib",
    ];
    unsafe {
        for name in candidates {
            let cname = CString::new(name).ok()?;
            let handle = libc::dlopen(cname.as_ptr(), libc::RTLD_NOW | libc::RTLD_LOCAL);
            if handle.is_null() {
                continue;
            }
            let get_info: Option<GetInfoFn> = sym(handle, "WebPGetInfo");
            let decode_rgba: Option<DecodeRgbaFn> = sym(handle, "WebPDecodeRGBA");
            let encode_rgba: Option<EncodeRgbaFn> = sym(handle, "WebPEncodeRGBA");
            let encode_lossless_rgba: Option<EncodeLosslessRgbaFn> = sym(handle, "WebPEncodeLosslessRGBA");
            let free: Option<FreeFn> = sym(handle, "WebPFree").or_else(|| sym(handle, "free"));
            if let (Some(a), Some(b), Some(c), Some(d), Some(e)) =
                (get_info, decode_rgba, encode_rgba, encode_lossless_rgba, free)
            {
                return Some(Lib {
                    get_info: a,
                    decode_rgba: b,
                    encode_rgba: c,
                    encode_lossless_rgba: d,
                    free: e,
                });
            }
        }
    }
    None
}

fn lib() -> Option<&'static Lib> {
    LIB.get_or_init(load).as_ref()
}

pub fn available() -> bool {
    lib().is_some()
}

pub fn decode(data: &[u8]) -> Result<Image, String> {
    let l = lib().ok_or_else(|| "null_decoder".to_string())?;
    unsafe {
        let mut w: c_int = 0;
        let mut h: c_int = 0;
        if (l.get_info)(data.as_ptr(), data.len(), &mut w, &mut h) == 0 || w <= 0 || h <= 0 {
            return Err("null_decoder".to_string());
        }
        let ptr = (l.decode_rgba)(data.as_ptr(), data.len(), &mut w, &mut h);
        if ptr.is_null() {
            return Err("null_decoder".to_string());
        }
        let n = w as usize * h as usize * 4;
        let pixels = std::slice::from_raw_parts(ptr, n).to_vec();
        (l.free)(ptr as *mut c_void);
        Ok(Image::from_rgba(w as u32, h as u32, pixels))
    }
}

pub fn encode(img: &Image, quality: Option<u32>) -> Result<Vec<u8>, String> {
    let l = lib().ok_or_else(|| "WebP encoder not available".to_string())?;
    unsafe {
        let mut out: *mut u8 = std::ptr::null_mut();
        let size = match quality {
            Some(q) => (l.encode_rgba)(
                img.data.as_ptr(),
                img.width as c_int,
                img.height as c_int,
                (img.width * 4) as c_int,
                q.min(100) as c_float,
                &mut out,
            ),
            None => (l.encode_lossless_rgba)(
                img.data.as_ptr(),
                img.width as c_int,
                img.height as c_int,
                (img.width * 4) as c_int,
                &mut out,
            ),
        };
        if size == 0 || out.is_null() {
            return Err("WebP encoding failed".to_string());
        }
        let v = std::slice::from_raw_parts(out, size).to_vec();
        (l.free)(out as *mut c_void);
        Ok(v)
    }
}

// ---------------------------------------------------------------------------
// RIFF container helpers
// ---------------------------------------------------------------------------

struct RiffChunk {
    fourcc: [u8; 4],
    data: Vec<u8>,
}

fn parse_chunks(data: &[u8]) -> Option<Vec<RiffChunk>> {
    if data.len() < 12 || &data[0..4] != b"RIFF" || &data[8..12] != b"WEBP" {
        return None;
    }
    let mut chunks = Vec::new();
    let mut p = 12usize;
    while p + 8 <= data.len() {
        let fourcc = [data[p], data[p + 1], data[p + 2], data[p + 3]];
        let len = u32::from_le_bytes([data[p + 4], data[p + 5], data[p + 6], data[p + 7]]) as usize;
        let end = (p + 8 + len).min(data.len());
        chunks.push(RiffChunk {
            fourcc,
            data: data[p + 8..end].to_vec(),
        });
        p = p + 8 + len + (len & 1);
    }
    Some(chunks)
}

fn build(chunks: &[RiffChunk]) -> Vec<u8> {
    let mut body = Vec::new();
    body.extend_from_slice(b"WEBP");
    for c in chunks {
        body.extend_from_slice(&c.fourcc);
        body.extend_from_slice(&(c.data.len() as u32).to_le_bytes());
        body.extend_from_slice(&c.data);
        if c.data.len() % 2 == 1 {
            body.push(0);
        }
    }
    let mut out = Vec::with_capacity(body.len() + 8);
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(body.len() as u32).to_le_bytes());
    out.extend_from_slice(&body);
    out
}

fn image_size(chunks: &[RiffChunk]) -> Option<(u32, u32)> {
    for c in chunks {
        match &c.fourcc {
            b"VP8X" if c.data.len() >= 10 => {
                let w = (c.data[4] as u32 | (c.data[5] as u32) << 8 | (c.data[6] as u32) << 16) + 1;
                let h = (c.data[7] as u32 | (c.data[8] as u32) << 8 | (c.data[9] as u32) << 16) + 1;
                return Some((w, h));
            }
            b"VP8 " if c.data.len() >= 10 => {
                let w = u16::from_le_bytes([c.data[6], c.data[7]]) as u32 & 0x3fff;
                let h = u16::from_le_bytes([c.data[8], c.data[9]]) as u32 & 0x3fff;
                return Some((w, h));
            }
            b"VP8L" if c.data.len() >= 5 => {
                let b = u32::from_le_bytes([c.data[1], c.data[2], c.data[3], c.data[4]]);
                return Some(((b & 0x3fff) + 1, ((b >> 14) & 0x3fff) + 1));
            }
            _ => {}
        }
    }
    None
}

/// Adds ICC and/or EXIF metadata chunks to an encoded WebP file.
pub fn add_metadata(webp: Vec<u8>, icc: Option<&[u8]>, exif: Option<&[u8]>) -> Vec<u8> {
    if icc.is_none() && exif.is_none() {
        return webp;
    }
    let mut chunks = match parse_chunks(&webp) {
        Some(c) => c,
        None => return webp,
    };
    let (w, h) = match image_size(&chunks) {
        Some(s) => s,
        None => return webp,
    };
    let mut ensure_vp8x = |chunks: &mut Vec<RiffChunk>, flag: u8| {
        if let Some(c) = chunks.iter_mut().find(|c| &c.fourcc == b"VP8X") {
            if c.data.len() >= 10 {
                c.data[0] |= flag;
            }
        } else {
            let mut d = vec![flag, 0, 0, 0];
            let wm = w - 1;
            let hm = h - 1;
            d.extend_from_slice(&[wm as u8, (wm >> 8) as u8, (wm >> 16) as u8]);
            d.extend_from_slice(&[hm as u8, (hm >> 8) as u8, (hm >> 16) as u8]);
            chunks.insert(
                0,
                RiffChunk {
                    fourcc: *b"VP8X",
                    data: d,
                },
            );
        }
    };
    if let Some(icc) = icc {
        ensure_vp8x(&mut chunks, 0x20);
        chunks.insert(
            1,
            RiffChunk {
                fourcc: *b"ICCP",
                data: icc.to_vec(),
            },
        );
    }
    if let Some(exif) = exif {
        if !chunks.iter().any(|c| &c.fourcc == b"VP8X") {
            ensure_vp8x(&mut chunks, 0x08);
        }
        chunks.push(RiffChunk {
            fourcc: *b"EXIF",
            data: exif.to_vec(),
        });
    }
    build(&chunks)
}

/// Extracts EXIF and ICC payloads from a WebP container.
pub fn metadata(data: &[u8]) -> (Option<Vec<u8>>, Option<Vec<u8>>) {
    let mut exif = None;
    let mut icc = None;
    if let Some(chunks) = parse_chunks(data) {
        for c in chunks {
            match &c.fourcc {
                b"EXIF" => exif = Some(c.data),
                b"ICCP" => icc = Some(c.data),
                _ => {}
            }
        }
    }
    (exif, icc)
}
