//! Compression pipeline: dispatches to the right codec depending on the input
//! and requested output format.

use crate::cli::{Args, ChromaSubsampling, OutputFormat};
use crate::codecs::{exif, gif, jpeg, jpeg_enc, png, quant, tiff, webp};
use crate::image::{resize, Image};
use crate::scan::{detect_kind, ImageKind};

#[derive(Debug)]
pub struct CompressError(pub String);

impl std::fmt::Display for CompressError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

fn err<T>(msg: impl Into<String>) -> Result<T, CompressError> {
    Err(CompressError(msg.into()))
}

const JPEG_DECODE_CODE: &str = "20104";
const PNG_DECODE_CODE: &str = "20204";
const WEBP_DECODE_CODE: &str = "20304";
const GIF_CODE: &str = "20409] [20411";

fn kind_to_format(kind: ImageKind) -> OutputFormat {
    match kind {
        ImageKind::Jpeg => OutputFormat::Jpeg,
        ImageKind::Png => OutputFormat::Png,
        ImageKind::Gif => OutputFormat::Gif,
        ImageKind::WebP => OutputFormat::WebP,
    }
}

/// Resize request derived from the command line.
#[derive(Clone, Copy)]
struct ResizeSpec {
    width: u32,
    height: u32,
    long_edge: u32,
    short_edge: u32,
    no_upscale: bool,
}

impl ResizeSpec {
    fn from_args(args: &Args) -> ResizeSpec {
        ResizeSpec {
            width: args.width,
            height: args.height,
            long_edge: args.long_edge,
            short_edge: args.short_edge,
            no_upscale: args.no_upscale,
        }
    }

    fn requested(&self) -> bool {
        self.width > 0 || self.height > 0 || self.long_edge > 0 || self.short_edge > 0
    }

    /// Computes the target dimensions for an image of `w` x `h`.
    /// `swapped` tells that the display orientation exchanges width/height.
    fn target(&self, w: u32, h: u32, swapped: bool) -> Option<(u32, u32)> {
        if !self.requested() {
            return None;
        }
        let ratio = |num: u32, target: u32, den: u32| -> u32 {
            ((num as f64 * target as f64 / den as f64).round() as u32).max(1)
        };
        let (mut tw, mut th) = (0u32, 0u32);
        if self.width > 0 || self.height > 0 {
            let (rw, rh) = if swapped {
                (self.height, self.width)
            } else {
                (self.width, self.height)
            };
            if rw > 0 && rh > 0 {
                tw = rw;
                th = rh;
            } else if rw > 0 {
                tw = rw;
                th = ratio(h, rw, w);
            } else {
                th = rh;
                tw = ratio(w, rh, h);
            }
        } else if self.long_edge > 0 {
            let (dw, dh) = if swapped { (h, w) } else { (w, h) };
            if dw >= dh {
                tw = self.long_edge;
                th = ratio(h, self.long_edge, w);
            } else {
                th = self.long_edge;
                tw = ratio(w, self.long_edge, h);
            }
        } else if self.short_edge > 0 {
            let (dw, dh) = if swapped { (h, w) } else { (w, h) };
            if dw < dh {
                tw = self.short_edge;
                th = ratio(h, self.short_edge, w);
            } else {
                th = self.short_edge;
                tw = ratio(w, self.short_edge, h);
            }
        }
        if self.no_upscale && (tw >= w || th >= h) {
            return None;
        }
        Some((tw.max(1), th.max(1)))
    }
}

fn maybe_resize(img: Image, spec: &ResizeSpec, swapped: bool) -> Image {
    match spec.target(img.width, img.height, swapped) {
        Some((w, h)) => resize(&img, w, h),
        None => img,
    }
}

fn chroma_of(args: &Args) -> (usize, usize) {
    match args.jpeg_chroma_subsampling {
        ChromaSubsampling::Cs444 => (1, 1),
        ChromaSubsampling::Cs422 => (2, 1),
        ChromaSubsampling::Cs420 | ChromaSubsampling::Auto => (2, 2),
        ChromaSubsampling::Cs411 => (4, 1),
    }
}

/// Metadata carried over when converting between formats.
#[derive(Default, Clone)]
struct Metadata {
    exif: Option<Vec<u8>>,
    icc: Option<Vec<u8>>,
}

fn png_metadata(p: &png::Png) -> Metadata {
    let mut m = Metadata::default();
    for c in p.before_idat.iter().chain(p.after_idat.iter()) {
        match &c.kind {
            b"eXIf" => m.exif = Some(c.data.clone()),
            b"iCCP" => {
                if let Some(zero) = c.data.iter().position(|&b| b == 0) {
                    if c.data.len() > zero + 2 {
                        if let Ok(d) = crate::codecs::deflate::zlib_decompress(&c.data[zero + 2..], 4096) {
                            m.icc = Some(d);
                        }
                    }
                }
            }
            _ => {}
        }
    }
    m
}

/// JPEG marker segments to carry into a re-encoded JPEG.
fn jpeg_markers(jp: &jpeg::Jpeg, args: &Args) -> Vec<jpeg::Marker> {
    if args.exif {
        jp.markers.clone()
    } else if args.strip_icc {
        Vec::new()
    } else {
        jp.markers
            .iter()
            .filter(|m| m.marker == 0xE2 && m.data.starts_with(b"ICC_PROFILE\0"))
            .cloned()
            .collect()
    }
}

fn icc_markers(icc: &[u8]) -> Vec<jpeg::Marker> {
    let chunks: Vec<&[u8]> = icc.chunks(65519 - 14).collect();
    let n = chunks.len() as u8;
    chunks
        .iter()
        .enumerate()
        .map(|(i, c)| {
            let mut d = Vec::with_capacity(c.len() + 14);
            d.extend_from_slice(b"ICC_PROFILE\0");
            d.push(i as u8 + 1);
            d.push(n);
            d.extend_from_slice(c);
            jpeg::Marker {
                marker: 0xE2,
                data: d,
            }
        })
        .collect()
}

fn exif_marker(exif: &[u8]) -> jpeg::Marker {
    let mut d = Vec::with_capacity(exif.len() + 6);
    d.extend_from_slice(b"Exif\0\0");
    d.extend_from_slice(exif);
    jpeg::Marker {
        marker: 0xE1,
        data: d,
    }
}

fn encode_jpeg_pixels(img: &Image, quality: Option<u32>, args: &Args, markers: Vec<jpeg::Marker>, force_components: Option<usize>) -> Vec<u8> {
    let gray = match force_components {
        Some(1) => true,
        Some(_) => false,
        None => img.is_gray(),
    };
    let (q, tables, jfif, chroma) = match quality {
        Some(q) => (q, jpeg_enc::QuantTables::Perceptual, (1, 1), chroma_of(args)),
        None => (75, jpeg_enc::QuantTables::AnnexK, (1, 2), (1, 1)),
    };
    let opts = jpeg_enc::EncodeOptions {
        progressive: !args.jpeg_baseline,
        jfif_version: jfif,
        markers,
    };
    let chroma = if gray { None } else { Some(chroma) };
    jpeg_enc::encode_image(img, q, chroma, tables, &opts)
}

fn compress_jpeg(data: &[u8], args: &Args, quality: Option<u32>) -> Result<Vec<u8>, CompressError> {
    let jp = match jpeg::decode(data) {
        Ok(j) => j,
        Err(e) => return err(format!("{} [{}]", e, JPEG_DECODE_CODE)),
    };
    let markers = jpeg_markers(&jp, args);
    let spec = ResizeSpec::from_args(args);
    let orientation = jpeg::exif_payload(&jp).and_then(|e| exif::orientation(&e)).unwrap_or(1);
    let swapped = (5..=8).contains(&orientation);
    if quality.is_none() && !spec.requested() {
        // Lossless transcode
        let opts = jpeg_enc::EncodeOptions {
            progressive: !args.jpeg_baseline,
            jfif_version: jp.jfif.unwrap_or((1, 1)),
            markers,
        };
        return Ok(jpeg_enc::encode_from_components(jp.width, jp.height, &jp.components, &jp.qt, &opts));
    }
    let img = jpeg::to_image(&jp);
    let img = maybe_resize(img, &spec, swapped);
    let ncomp = jp.components.len();
    let force = if ncomp == 1 { Some(1) } else { Some(3) };
    Ok(encode_jpeg_pixels(&img, quality, args, markers, force))
}

fn compress_png(data: &[u8], args: &Args, quality: Option<u32>) -> Result<Vec<u8>, CompressError> {
    let spec = ResizeSpec::from_args(args);
    let level = args.png_opt_level;
    if quality.is_none() && !spec.requested() {
        return match png::optimize_lossless(data, level) {
            Ok(v) => Ok(v),
            Err(e) => err(format!("{} [{}]", e, PNG_DECODE_CODE)),
        };
    }
    let decoded = match png::decode(data) {
        Ok(p) => p,
        Err(e) => return err(format!("{} [{}]", e, PNG_DECODE_CODE)),
    };
    let img = png::to_image(&decoded);
    let img = maybe_resize(img, &spec, false);
    match quality {
        None => Ok(png::encode_rgba_lossless(&img, level, &decoded.before_idat, &decoded.after_idat)),
        Some(q) => {
            let qz = quant::quantize(&img, q, 256);
            Ok(png::encode_indexed(img.width, img.height, &qz.indices, &qz.palette, level, &[], &[]))
        }
    }
}

fn compress_webp(data: &[u8], args: &Args, quality: Option<u32>) -> Result<Vec<u8>, CompressError> {
    let img = match webp::decode(data) {
        Ok(i) => i,
        Err(e) => return err(format!("{} [{}]", e, WEBP_DECODE_CODE)),
    };
    let spec = ResizeSpec::from_args(args);
    let quality = if quality.is_none() && spec.requested() { Some(100) } else { quality };
    let img = maybe_resize(img, &spec, false);
    let encoded = match webp::encode(&img, quality) {
        Ok(v) => v,
        Err(e) => return err(format!("{} [{}]", e, WEBP_DECODE_CODE)),
    };
    if args.exif {
        let (exif_data, icc) = webp::metadata(data);
        Ok(webp::add_metadata(encoded, icc.as_deref(), exif_data.as_deref()))
    } else {
        Ok(encoded)
    }
}

fn compress_gif(data: &[u8], args: &Args, quality: Option<u32>) -> Result<Vec<u8>, CompressError> {
    let g = match gif::decode(data) {
        Ok(g) => g,
        Err(e) => return err(format!("{} [{}]", e, GIF_CODE)),
    };
    let spec = ResizeSpec::from_args(args);
    let g = match spec.target(g.width as u32, g.height as u32, false) {
        Some((tw, th)) if g.width > 0 && g.height > 0 => resize_gif(&g, tw, th, quality.unwrap_or(100)),
        _ => g,
    };
    Ok(gif::reencode(&g, quality))
}

/// Resizes every frame of a GIF independently.
fn resize_gif(g: &gif::Gif, tw: u32, th: u32) -> gif::Gif {
    let sx = tw as f64 / g.width as f64;
    let sy = th as f64 / g.height as f64;
    let mut out = g.clone();
    out.width = tw as u16;
    out.height = th as u16;
    out.frames.clear();
    for f in &g.frames {
        let palette = f
            .local_palette
            .as_ref()
            .or(g.global_palette.as_ref())
            .cloned()
            .unwrap_or_else(|| vec![[0, 0, 0]; 2]);
        let mut img = Image::new(f.width as u32, f.height as u32);
        for (i, &idx) in f.indices.iter().enumerate() {
            let c = palette.get(idx as usize).copied().unwrap_or([0, 0, 0]);
            let a = if Some(idx) == f.transparent { 0 } else { 255 };
            img.data[i * 4..i * 4 + 4].copy_from_slice(&[c[0], c[1], c[2], a]);
        }
        let nw = ((f.width as f64 * sx).round() as u32).max(1);
        let nh = ((f.height as f64 * sy).round() as u32).max(1);
        let resized = resize(&img, nw, nh);
        let has_alpha = resized.data.chunks_exact(4).any(|p| p[3] < 128);
        let mut opaque = resized.clone();
        for p in opaque.data.chunks_exact_mut(4) {
            p[3] = 255;
        }
        let q = quant::quantize(&opaque, 100, if has_alpha { 255 } else { 256 });
        let mut pal: Vec<[u8; 3]> = q.palette.iter().map(|c| [c[0], c[1], c[2]]).collect();
        let mut indices = q.indices;
        let mut transparent = None;
        if has_alpha {
            let t = pal.len() as u8;
            pal.push([0, 0, 0]);
            for (i, p) in resized.data.chunks_exact(4).enumerate() {
                if p[3] < 128 {
                    indices[i] = t;
                }
            }
            transparent = Some(t);
        }
        out.frames.push(gif::Frame {
            left: (f.left as f64 * sx).round() as u16,
            top: (f.top as f64 * sy).round() as u16,
            width: nw as u16,
            height: nh as u16,
            local_palette: Some(pal),
            interlaced: false,
            indices,
            transparent,
            delay: f.delay,
            disposal: f.disposal,
            user_input: f.user_input,
            has_gce: true,
            extensions: f.extensions.clone(),
        });
    }
    out
}

/// Decodes any supported input into RGBA plus metadata.
fn decode_any(data: &[u8], kind: ImageKind) -> Result<(Image, Metadata, Option<usize>), CompressError> {
    match kind {
        ImageKind::Jpeg => {
            let jp = match jpeg::decode(data) {
                Ok(j) => j,
                Err(e) => return err(format!("{} [{}]", e, JPEG_DECODE_CODE)),
            };
            let meta = Metadata {
                exif: jpeg::exif_payload(&jp),
                icc: jpeg::icc_profile(&jp),
            };
            let n = jp.components.len();
            Ok((jpeg::to_image(&jp), meta, Some(n)))
        }
        ImageKind::Png => {
            let p = match png::decode(data) {
                Ok(p) => p,
                Err(e) => return err(format!("{} [{}]", e, PNG_DECODE_CODE)),
            };
            let meta = png_metadata(&p);
            Ok((png::to_image(&p), meta, None))
        }
        ImageKind::WebP => {
            let img = match webp::decode(data) {
                Ok(i) => i,
                Err(e) => return err(format!("{} [{}]", e, WEBP_DECODE_CODE)),
            };
            let (exif_data, icc) = webp::metadata(data);
            Ok((img, Metadata { exif: exif_data, icc }, None))
        }
        ImageKind::Gif => {
            let g = match gif::decode(data) {
                Ok(g) => g,
                Err(e) => return err(format!("{} [{}]", e, GIF_CODE)),
            };
            match gif::first_frame_image(&g) {
                Ok(img) => Ok((img, Metadata::default(), None)),
                Err(e) => err(format!("{} [{}]", e, GIF_CODE)),
            }
        }
    }
}

fn convert(data: &[u8], kind: ImageKind, args: &Args, quality: Option<u32>) -> Result<Vec<u8>, CompressError> {
    let (mut img, meta, ncomp) = decode_any(data, kind)?;
    let meta = if args.exif { meta } else { Metadata::default() };
    if let Some(ex) = &meta.exif {
        if let Some(o) = exif::orientation(ex) {
            if o != 1 {
                img = img.apply_orientation(o);
            }
        }
    }
    let spec = ResizeSpec::from_args(args);
    let img = maybe_resize(img, &spec, false);
    match args.format {
        OutputFormat::Jpeg => {
            let mut markers = Vec::new();
            if let Some(icc) = &meta.icc {
                markers.extend(icc_markers(icc));
            }
            if let Some(ex) = &meta.exif {
                markers.push(exif_marker(ex));
            }
            let force = match ncomp {
                Some(1) => Some(1),
                Some(_) => Some(3),
                None => None,
            };
            Ok(encode_jpeg_pixels(&img, quality, args, markers, force))
        }
        OutputFormat::Png => {
            let mut before = Vec::new();
            let mut after = Vec::new();
            if let Some(icc) = &meta.icc {
                let mut d = Vec::new();
                d.extend_from_slice(b"icc\0\0");
                d.extend_from_slice(&crate::codecs::deflate::zlib_compress(icc, 9));
                before.push(png::Chunk { kind: *b"iCCP", data: d });
            }
            if let Some(ex) = &meta.exif {
                after.push(png::Chunk {
                    kind: *b"eXIf",
                    data: ex.clone(),
                });
            }
            match quality {
                None => Ok(png::encode_rgba_lossless(&img, args.png_opt_level, &before, &after)),
                Some(q) => {
                    let qz = quant::quantize(&img, q, 256);
                    Ok(png::encode_indexed(img.width, img.height, &qz.indices, &qz.palette, args.png_opt_level, &before, &after))
                }
            }
        }
        OutputFormat::WebP => {
            let encoded = match webp::encode(&img, quality) {
                Ok(v) => v,
                Err(e) => return err(format!("{} [{}]", e, WEBP_DECODE_CODE)),
            };
            Ok(webp::add_metadata(encoded, meta.icc.as_deref(), meta.exif.as_deref()))
        }
        OutputFormat::Gif => Ok(gif::encode_image(&img, quality.unwrap_or(100))),
        OutputFormat::Tiff => Ok(tiff::encode(&img)),
        OutputFormat::Original => unreachable!(),
    }
}

/// Compresses with the given quality (`None` means lossless).
fn compress_with_quality(data: &[u8], kind: ImageKind, args: &Args, quality: Option<u32>) -> Result<Vec<u8>, CompressError> {
    if args.format != OutputFormat::Original {
        if args.format == kind_to_format(kind) {
            return err("Cannot convert to the same format [10407]");
        }
        return convert(data, kind, args, quality);
    }
    match kind {
        ImageKind::Jpeg => compress_jpeg(data, args, quality),
        ImageKind::Png => compress_png(data, args, quality),
        ImageKind::WebP => compress_webp(data, args, quality),
        ImageKind::Gif => compress_gif(data, args, quality),
    }
}

/// Searches for the quality producing the largest file not exceeding `max`.
fn compress_to_size(data: &[u8], kind: ImageKind, args: &Args, max: u64) -> Result<Vec<u8>, CompressError> {
    let tolerance = max / 50;
    let mut quality: u32 = 80;
    let mut last_less: u32 = 1;
    let mut last_high: u32 = 101;
    let mut tries = 0u32;
    loop {
        let compressed = compress_with_quality(data, kind, args, Some(quality))?;
        let size = compressed.len() as u64;
        if size <= max && size >= max.saturating_sub(tolerance) {
            return Ok(compressed);
        }
        if size <= max {
            last_less = quality;
        } else {
            last_high = quality;
        }
        let last_quality = quality;
        quality = ((last_high + last_less) / 2).clamp(1, 100);
        tries += 1;
        if last_quality == quality || tries >= 10 {
            return Ok(compressed);
        }
    }
}

pub fn compress(data: &[u8], args: &Args) -> Result<Vec<u8>, CompressError> {
    let kind = match detect_kind(data) {
        Some(k) => k,
        None => return err("Unknown file type [10001]"),
    };
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if let Some(max) = args.max_size {
            compress_to_size(data, kind, args, max)
        } else if args.lossless {
            compress_with_quality(data, kind, args, None)
        } else {
            compress_with_quality(data, kind, args, Some(args.quality.unwrap_or(80)))
        }
    }));
    match result {
        Ok(r) => r,
        Err(_) => err("Internal error while compressing [10002]"),
    }
}
