new='''/// Upsamples a component plane to full resolution (w x h), using the
/// triangle ("fancy") filter for the common 2x cases.
fn upsample(jp: &Jpeg, ci: usize, plane: &[u8], pw: usize) -> Vec<u8> {
    let c = &jp.components[ci];
    let w = jp.width as usize;
    let h = jp.height as usize;
    let hf = jp.hmax / c.h;
    let vf = jp.vmax / c.v;
    // actual downsampled dimensions
    let cw = (w * c.h + jp.hmax - 1) / jp.hmax;
    let ch = (h * c.v + jp.vmax - 1) / jp.vmax;
    let mut out = vec![0u8; w * h];
    if hf == 1 && vf == 1 {
        for y in 0..h {
            out[y * w..(y + 1) * w].copy_from_slice(&plane[y * pw..y * pw + w]);
        }
        return out;
    }
    if hf == 2 && vf == 1 && jp.hmax % c.h == 0 {
        for y in 0..h {
            let row = &plane[y * pw..y * pw + cw];
            let orow = &mut out[y * w..(y + 1) * w];
            for i in 0..cw {
                let cur = row[i] as u32 * 3;
                let prev = if i == 0 { row[0] } else { row[i - 1] } as u32;
                let next = if i + 1 >= cw { row[cw - 1] } else { row[i + 1] } as u32;
                let a = if i == 0 { row[0] as u32 } else { (cur + prev + 1) >> 2 };
                let b = if i + 1 >= cw { row[cw - 1] as u32 } else { (cur + next + 2) >> 2 };
                if 2 * i < w {
                    orow[2 * i] = a as u8;
                }
                if 2 * i + 1 < w {
                    orow[2 * i + 1] = b as u8;
                }
            }
        }
        return out;
    }
    if hf == 2 && vf == 2 && jp.hmax % c.h == 0 && jp.vmax % c.v == 0 {
        let mut colsum = vec![0u32; cw];
        for y in 0..h {
            let sy = y / 2;
            let near = &plane[sy * pw..sy * pw + cw];
            let other_y = if y % 2 == 0 { sy.saturating_sub(1) } else { (sy + 1).min(ch - 1) };
            let far = &plane[other_y * pw..other_y * pw + cw];
            for i in 0..cw {
                colsum[i] = near[i] as u32 * 3 + far[i] as u32;
            }
            let orow = &mut out[y * w..(y + 1) * w];
            for i in 0..cw {
                let cur = colsum[i] * 3;
                let a = if i == 0 {
                    (colsum[0] * 4 + 8) >> 4
                } else {
                    (cur + colsum[i - 1] + 8) >> 4
                };
                let b = if i + 1 >= cw {
                    (colsum[cw - 1] * 4 + 7) >> 4
                } else {
                    (cur + colsum[i + 1] + 7) >> 4
                };
                if 2 * i < w {
                    orow[2 * i] = a as u8;
                }
                if 2 * i + 1 < w {
                    orow[2 * i + 1] = b as u8;
                }
            }
        }
        return out;
    }
    // generic replication
    for y in 0..h {
        let sy = (y * c.v / jp.vmax).min(ch - 1);
        for x in 0..w {
            let sx = (x * c.h / jp.hmax).min(cw - 1);
            out[y * w + x] = plane[sy * pw + sx];
        }
    }
    out
}

/// Converts decoded coefficients into an RGBA8 image.
pub fn to_image(jp: &Jpeg) -> Image {
    let w = jp.width as usize;
    let h = jp.height as usize;
    let n = jp.components.len();
    let planes: Vec<Vec<u8>> = (0..n)
        .map(|i| {
            let (plane, pw, _) = component_plane(jp, i);
            upsample(jp, i, &plane, pw)
        })
        .collect();
    let mut out = vec![255u8; w * h * 4];
    let rgb_cs = is_rgb_colorspace(jp);
    let adobe_inverted = jp.adobe_transform.is_some();
    for i in 0..w * h {
        let o = i * 4;
        match n {
            1 => {
                let g = planes[0][i];
                out[o] = g;
                out[o + 1] = g;
                out[o + 2] = g;
            }
            3 => {
                let c0 = planes[0][i] as i32;
                let c1 = planes[1][i] as i32;
                let c2 = planes[2][i] as i32;
                if rgb_cs {
                    out[o] = c0 as u8;
                    out[o + 1] = c1 as u8;
                    out[o + 2] = c2 as u8;
                } else {
                    let (r, g, b) = ycc_to_rgb(c0, c1, c2);
                    out[o] = r;
                    out[o + 1] = g;
                    out[o + 2] = b;
                }
            }
            4 => {
                let c0 = planes[0][i] as i32;
                let c1 = planes[1][i] as i32;
                let c2 = planes[2][i] as i32;
                let k = planes[3][i] as i32;
                let (mut c, mut m, mut yy) = (c0, c1, c2);
                if jp.adobe_transform == Some(2) {
                    let (r, g, b) = ycc_to_rgb(c0, c1, c2);
                    c = r as i32;
                    m = g as i32;
                    yy = b as i32;
                }
                let (c, m, yy, k) = if adobe_inverted {
                    (c, m, yy, k)
                } else {
                    (255 - c, 255 - m, 255 - yy, 255 - k)
                };
                out[o] = clamp_u8(c * k / 255);
                out[o + 1] = clamp_u8(m * k / 255);
                out[o + 2] = clamp_u8(yy * k / 255);
            }
            _ => {
                let g = planes[0][i];
                out[o] = g;
                out[o + 1] = g;
                out[o + 2] = g;
            }
        }
    }
    Image::from_rgba(jp.width, jp.height, out)
}

