    let mut err_cur = vec![0f32; (w + 2) * 4];
    let mut err_next = vec![0f32; (w + 2) * 4];
    for y in 0..h {
        for e in err_next.iter_mut() {
            *e = 0.0;
        }
        let serpentine = y % 2 == 1;
        for xi in 0..w {
            let x = if serpentine { w - 1 - xi } else { xi };
            let p = &img.data[(y * w + x) * 4..(y * w + x) * 4 + 4];
