/// color when the colors are close enough.
fn smooth_runs(indices: &[u8], width: usize, palette: &[[u8; 3]], transparent: Option<u8>, thr: u32) -> Vec<u8> {
    let mut out = indices.to_vec();
    if width == 0 || palette.is_empty() {
        return out;
    }
    let dist = |a: u8, b: u8| -> u32 {
        let pa = palette.get(a as usize).copied().unwrap_or([0, 0, 0]);
        let pb = palette.get(b as usize).copied().unwrap_or([0, 0, 0]);
        let dr = pa[0] as i32 - pb[0] as i32;
        let dg = pa[1] as i32 - pb[1] as i32;
        let db = pa[2] as i32 - pb[2] as i32;
        (dr * dr + dg * dg + db * db) as u32
    };
    for row in out.chunks_mut(width) {
        for x in 1..row.len() {
            let prev = row[x - 1];
            let cur = row[x];
            if cur == prev || Some(cur) == transparent || Some(prev) == transparent {
                continue;
            }
            if dist(cur, prev) <= thr {
                row[x] = prev;
            }
        }
    }
    out
}

