/// Encodes one block of an AC refinement scan (successive approximation).
fn encode_block_refine(sink: &mut Sink, coeffs: &[i16], ac_tbl: usize, scan: &ScanSpec, st: &mut ScanState) {
    let mut absvalues = [0u32; 64];
    let mut eob = 0usize;
    for k in scan.ss..=scan.se {
        let v = coeffs[ZIGZAG[k]] as i32;
        let a = (v.unsigned_abs()) >> scan.al;
        absvalues[k] = a;
        if a == 1 {
            eob = k;
        }
    }
    let mut r = 0u32;
    let mut br: Vec<u8> = Vec::new();
    for k in scan.ss..=scan.se {
        let temp = absvalues[k];
        if temp == 0 {
            r += 1;
            continue;
        }
        while r > 15 && k <= eob {
            emit_eobrun(sink, ac_tbl, st);
            sink.ac_symbol(ac_tbl, 0xF0);
            r -= 16;
            for &b in &br {
                sink.bits(b as u32, 1);
            }
            br.clear();
        }
        if temp > 1 {
            br.push((temp & 1) as u8);
            continue;
        }
        emit_eobrun(sink, ac_tbl, st);
        sink.ac_symbol(ac_tbl, ((r << 4) + 1) as u8);
        let sign = if coeffs[ZIGZAG[k]] < 0 { 0 } else { 1 };
        sink.bits(sign, 1);
        for &b in &br {
            sink.bits(b as u32, 1);
        }
        br.clear();
        r = 0;
    }
    if r > 0 || !br.is_empty() {
        st.eobrun += 1;
        st.be_buffer.extend_from_slice(&br);
        if st.eobrun == 0x7FFF || st.be_buffer.len() > 937 {
            emit_eobrun(sink, ac_tbl, st);
        }
    }
}''')

