{"command":"cd /workspace && python3 - <<'EOF'
p='src/codecs/jpeg_enc.rs'
s=open(p).read()
old=s[s.index('/// Estimates the coded size (in bits) of a scan sequence.'):s.index('fn build_scan_script(')]
new='''/// Computes the exact coded size (in bytes) of a scan sequence by running
/// the entropy coder.
fn estimate_scans(comps: &[Component], scans: &[ScanSpec], mcux: usize, mcuy: usize) -> u64 {
    let mut total = 0u64;
    for scan in scans {
        let (_, w) = encode_scan(comps, scan, true, mcux, mcuy);
        total += w.out.len() as u64 + 12;
    }
    total
}

/// Gathers statistics, builds the optimal tables and entropy codes a scan.
/// Returns the DHT payload entries and the coded data.
fn encode_scan(
    comps: &[Component],
    scan: &ScanSpec,
    progressive: bool,
    mcux: usize,
    mcuy: usize,
) -> (Vec<(u8, u8, HuffTable)>, BitWriter) {
    let mut dc_freq = [[0u32; 256]; 4];
    let mut ac_freq = [[0u32; 256]; 4];
    let mut bits = 0u64;
    {
        let mut sink = Sink::Count {
            dc: &mut dc_freq,
            ac: &mut ac_freq,
            bits: &mut bits,
        };
        run_scan(&mut sink, comps, scan, progressive, mcux, mcuy);
    }
    let mut dc_tables: [Option<HuffTable>; 4] = [None, None, None, None];
    let mut ac_tables: [Option<HuffTable>; 4] = [None, None, None, None];
    let mut dht_list: Vec<(u8, u8, HuffTable)> = Vec::new();
    let mut tbl_ids: Vec<usize> = scan.comps.iter().map(|&c| table_id(c)).collect();
    tbl_ids.sort_unstable();
    tbl_ids.dedup();
    for &t in &tbl_ids {
        if scan.ss == 0 {
            let dct = HuffTable::from_freq(&dc_freq[t]);
            dht_list.push((0, t as u8, dct.clone()));
            dc_tables[t] = Some(dct);
        }
        if scan.se > 0 {
            let act = HuffTable::from_freq(&ac_freq[t]);
            dht_list.push((1, t as u8, act.clone()));
            ac_tables[t] = Some(act);
        }
    }
    let mut w = BitWriter::new();
    {
        let mut sink = Sink::Write {
            dc: &dc_tables,
            ac: &ac_tables,
            w: &mut w,
        };
        run_scan(&mut sink, comps, scan, progressive, mcux, mcuy);
    }
    w.flush();
    for (_, _, t) in &dht_list {
        w.out.reserve(17 + t.symbols.len());
    }
    (dht_list, w)
}

