pub fn encode_indexed(width: u32, height: u32, indices: &[u8], palette: &[[u8; 4]], level: u8, before: &[Chunk], after: &[Chunk]) -> Vec<u8> {
    let w = width as usize;
    let h = height as usize;
    let n = palette.len().min(256);
    // Keep only used colors and sort transparent entries first.
    let mut used = vec![false; 256];
