    order.sort_by_key(|&i| (palette[i][3], palette[i][0], palette[i][1], palette[i][2]));
    let mut remap = vec![0u8; 256];
    for (new_i, &old_i) in order.iter().enumerate() {
        remap[old_i] = new_i as u8;
    }
    let sorted: Vec<[u8; 4]> = order.iter().map(|&i| palette[i]).collect();
    let remapped: Vec<u8> = indices.iter().map(|&i| remap[i as usize]).collect();
    let mut cands: Vec<Candidate> = Vec::new();

    let pal_rgb: Vec<[u8; 3]> = sorted.iter().map(|c| [c[0], c[1], c[2]]).collect();
    let mut trns: Vec<u8> = sorted.iter().map(|c| c[3]).collect();
    while trns.last() == Some(&255) {
        trns.pop();
    }
    let bits = if sorted.len() <= 2 {
        1
    } else if sorted.len() <= 4 {
        2
    } else if sorted.len() <= 16 {
        4
    } else {
        8
    };
    cands.push(Candidate {
        bit_depth: bits as u8,
        color_type: 3,
        palette: pal_rgb,
        trns: if trns.is_empty() { None } else { Some(trns) },
        raw: pack_indices(&remapped, w, h, bits),
    });

    let opaque = sorted.iter().all(|c| c[3] == 255);
    let gray = sorted.iter().all(|c| c[0] == c[1] && c[1] == c[2]);
    if gray && opaque {
        let values: Vec<u8> = remapped.iter().map(|&i| sorted[i as usize][0]).collect();
        let gbits = if sorted.iter().all(|c| c[0] == 0 || c[0] == 255) {
            1
        } else if sorted.iter().all(|c| c[0] % 85 == 0) {
            2
        } else if sorted.iter().all(|c| c[0] % 17 == 0) {
            4
        } else {
            8
        };
        let raw = if gbits == 8 {
            values
        } else {
            let div = 255 / ((1u16 << gbits) - 1) as u8;
            let scaled: Vec<u8> = values.iter().map(|&v| v / div).collect();
            pack_indices(&scaled, w, h, gbits)
        };
        cands.push(Candidate {
            bit_depth: gbits as u8,
            color_type: 0,
            palette: Vec::new(),
            trns: None,
            raw,
        });
    } else if opaque && sorted.len() > 16 && w * h <= 1 << 16 {
        // Small images may be cheaper as plain RGB.
        let mut raw = Vec::with_capacity(w * h * 3);
        for &i in &remapped {
            let c = sorted[i as usize];
            raw.extend_from_slice(&c[..3]);
        }
        cands.push(Candidate {
            bit_depth: 8,
            color_type: 2,
            palette: Vec::new(),
            trns: None,
            raw,
        });
    }

    let before: Vec<Chunk> = before.iter().filter(|c| keep_chunk(&c.kind)).cloned().collect();
    let after: Vec<Chunk> = after.iter().filter(|c| keep_chunk(&c.kind)).cloned().collect();
    let mut best: Option<Vec<u8>> = None;
    for c in &cands {
        let input = EncodeInput {
            width,
            height,
            bit_depth: c.bit_depth,
            color_type: c.color_type,
            palette: &c.palette,
            trns: c.trns.as_deref(),
            raw: &c.raw,
            before_idat: &before,
            after_idat: &after,
        };
        let enc = encode(&input, level);
        if best.as_ref().map(|b| enc.len() < b.len()).unwrap_or(true) {
            best = Some(enc);
        }
    }
    best.unwrap_or_default()
}
